prompt --application/shared_components/user_interface/lovs/siblings_fee_plan_lov
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(88547433834408653258)
,p_lov_name=>'SIBLINGS_FEE_PLAN_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    sb.STUDENT_ID AS Admission_No,',
'    sb.STUDENT_NAME || '' '' || sb.LAST_NAME AS SIBLING_NAME',
'FROM STUDENTS ms',
'JOIN STUDENTS sb ON sb.site_id = ms.site_id',
'JOIN CLASSES c ON sb.CLASS_ID = c.CLASS_ID',
'JOIN STUDENT_PARENTS p ON sb.STUDENT_ID = p.STUDENT_ID AND sb.SITE_ID = p.SITE_ID',
'WHERE ms.site_id = :APP_SITE_ID',
'  AND ms.student_id = :P95_ADMISSON_NO',
'  AND sb.student_id IN (',
'    SELECT student_id',
'    FROM STUDENTS',
'    START WITH student_id = :P95_ADMISSON_NO',
'             AND site_id = :APP_SITE_ID',
'    CONNECT BY NOCYCLE',
'      (PRIOR student_id = sibling_ad_no OR PRIOR sibling_ad_no = student_id)',
'      AND PRIOR site_id = site_id',
'  )',
'  AND sb.CLASS_ID = :CLASS_ID   -- filter siblings by the input class here',
'ORDER BY sb.student_id;',
''))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'ADMISSION_NO'
,p_display_column_name=>'ADMISSION_NO'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
,p_version_scn=>15656398682276
);
wwv_flow_imp_shared.create_list_of_values_cols(
 p_id=>wwv_flow_imp.id(88548165635311658977)
,p_query_column_name=>'ADMISSION_NO'
,p_heading=>'Sibling Admission#'
,p_display_sequence=>10
,p_data_type=>'VARCHAR2'
);
wwv_flow_imp_shared.create_list_of_values_cols(
