,p_lov_name=>'TEACHER_ASSIGN_STUDENT_LOV'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT scs.STUDENT_SCHEDULE_ID,S.STUDENT_ID,STUDENT_NAME||'' ''||LAST_NAME STUDENT_NAME,CLASS_NAME SCHOOL_YEAR,SB.SUBJECT_NAME SUBJECT,B.BOOK_NAME BOOK,CS.WEEKDAY,CS.START_TIME,CS.END_TIME,SB.SUBJECT_ID,C.CLASS_ID',
'  FROM STUDENTS S, CLASSES C,STUDENT_CLASSES_SCHEDULE SCS,CLASS_SCHEDULE CS,SUBJECTS SB,BOOKS B',
' WHERE SCS.CLASS_ID=C.CLASS_ID ',
'   AND SCS.CLASS_SHEDULE_ID=CS.SCHEDULE_ID',
'   AND SCS.SITE_ID=CS.SITE_ID',
'   AND SCS.SUBJECT_ID=SB.SUBJECT_ID',
'   AND SCS.BOOK_ID=B.BOOK_ID(+)',
'   AND S.STATUS=''A''',
'   AND SCS.STATUS=''A''',
'   AND CS.STATUS=''A''',
'   AND S.SITE_ID=:APP_SITE_ID',
