,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Books record transfer'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    INSERT INTO BOOKS(BOOK_NAME,SUBJECT_ID,CLASS_ID,STATUS,FEED_BY,FEED_DATE,SITE_ID)',
'    SELECT BOOK_NAME,SUBJECT_ID,CLASS_ID,STATUS,:APP_USER,TRUNC(SYSDATE),:P27_BRANCH',
'      FROM BOOKS S',
'     WHERE S.SITE_ID   =:APP_SITE_ID',
'       AND S.CLASS_ID  =NVL(:P27_SCHOOL_YEAR,S.CLASS_ID)',
'       AND S.SUBJECT_ID=NVL(:P27_SUBEJCT,S.SUBJECT_ID)',
'       AND S.BOOK_ID   =NVL(:P27_BOOK,S.BOOK_ID)',
'       AND STATUS      =''A''',
'       AND (BOOK_NAME,SUBJECT_ID,CLASS_ID) NOT IN (SELECT BOOK_NAME,SUBJECT_ID,CLASS_ID',
'                                                    FROM BOOKS S',
'                                                   WHERE SITE_ID=:P27_BRANCH',
'                                                  )',
'     ; ',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(20640475125005856129)
,p_process_when=>'P27_BRANCH'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_process_success_message=>'Record Transfer successfully.'
,p_internal_uid=>20640475290390856130
);
end;
