,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT SA.ASSESSMENT_ID,TO_CHAR(SA.ASSESSMENT_DATE,''DD-MON-YYYY'')ASSESSMENT_DATE,FIRST_NAME,LAST_NAME,GENDER,SA.PARENT_NAME,RELATION,CONTACT_NO,OCCUPATION,POSTCODE,ADDRESS,EME_CONTACT,EMAIL',
