wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(77625081173025605103)
,p_event_id=>wwv_flow_imp.id(30767317007402546301)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Get Stage'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P30_CLASS_ID IS NOT NULL THEN',
'     SELECT ',
'           CASE ',
'              WHEN year_number BETWEEN 1 AND 8  THEN ''K''',
'              WHEN year_number BETWEEN 9 AND 11 THEN ''G''',
'              WHEN year_number BETWEEN 12 AND 13 THEN ''A''',
'              ELSE NULL',
'           END AS STAGE INTO :P30_STAGE',
'      FROM   CLASSES',
'      WHERE  CLASS_ID = :P30_CLASS_ID',
'      ;',
'END IF',
';'))
,p_attribute_02=>'P30_CLASS_ID'
,p_attribute_03=>'P30_STAGE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_da_action_comment=>'STOP BECAUSE ID IS NOW GENERATED SEQUNCE WISE EVERY STUDENT'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(79419820863324254146)
,p_event_id=>wwv_flow_imp.id(30767317007402546301)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'Get Fees From Fee Plan'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT F.ADMISSION_FEE,BOOKS_FEE,PAST_PAPERS_FEE',
'           INTO :P30_REGISTRATION_FEE,:P30_BOOK_FEE,:P30_PAST_PAPER_FEE',
'  FROM FEE_PLAN F',
' WHERE F.CLASS_ID = :P30_CLASS_ID',
'   AND SITE_ID    = :APP_SITE_ID ',
'   AND STATUS = ''A''',
'   ;',
'EXCEPTION WHEN NO_DATA_FOUND THEN',
'  NULL;   '))
,p_attribute_02=>'P30_CLASS_ID'
,p_attribute_03=>'P30_REGISTRATION_FEE,P30_BOOK_FEE,P30_PAST_PAPER_FEE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'FUNCTION_BODY'
,p_server_condition_expr1=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'BEGIN  ',
'    SELECT COUNT(*) INTO V_CNT ',
'      FROM STUDENT_FEES F     ',
'     WHERE F.STUDENT_ID = :P30_STUDENT_ID_1',
'       AND F.SITE_ID    = :APP_SITE_ID',
'       ;',
'      IF V_CNT > 0 THEN',
'        RETURN FALSE;',
'      ELSE',
'         RETURN TRUE;',
'      END IF;',
'END;     '))
,p_server_condition_expr2=>'PLSQL'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(30767317147303546302)
,p_event_id=>wwv_flow_imp.id(30767317007402546301)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_MAX_STUDENT_ID NUMBER;',
'   V_CLASS_STAGE VARCHAR2(1);',
'   V_STUDENT VARCHAR2(20);',
'  BEGIN',
'  IF :P30_CLASS_ID IS NOT NULL AND (:P30_STATUS <> ''P'' OR :P30_STATUS IS NULL) THEN',
'      SELECT COUNT(*) INTO V_STUDENT',
'        FROM STUDENTS S',
'       WHERE STUDENT_ID=:P30_STUDENT_ID_1',
'         AND SITE_ID=:APP_SITE_ID',
'         ;   ',
'        SELECT SUBSTR(STAGE_TYPE,1,1) INTO V_CLASS_STAGE',
'           FROM CLASSES',
'          WHERE CLASS_ID=:P30_CLASS_ID',
'          ;  ',
'          IF V_CLASS_STAGE=''K'' THEN',
'            SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),300)+1 INTO V_MAX_STUDENT_ID',
'              FROM STUDENTS S',
'             WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'               AND S.SITE_ID=:APP_SITE_ID ',
'            ;',
'          ELSIF V_CLASS_STAGE=''G'' THEN',
'               SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),500)+1 INTO V_MAX_STUDENT_ID',
'              FROM STUDENTS S',
'             WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'               AND S.SITE_ID=:APP_SITE_ID ',
'             ;',
'          ELSIF V_CLASS_STAGE=''A'' THEN',
'               SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),100)+1 INTO V_MAX_STUDENT_ID',
'              FROM STUDENTS S',
'             WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'               AND S.SITE_ID=:APP_SITE_ID ',
'         ;       ',
'        END IF;',
'        ',
'        SELECT NVL(MAX(STUDENT_ID),100)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE  S.SITE_ID=:APP_SITE_ID ',
'         ;',
'        IF V_STUDENT = 0 THEN  ',
'           :P30_STUDENT_ID_1:=V_CLASS_STAGE||V_MAX_STUDENT_ID;',
'        END IF;    ',
' END IF; ',
'END;  '))
,p_attribute_02=>'APP_SITE_ID,P30_CLASS_ID,P30_STUDENT_ID_1,P30_FEE_STATUS'
,p_attribute_03=>'P30_STUDENT_ID_1'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
,p_da_action_comment=>'STOP BECAUSE ID IS NOW GENERATED SEQUNCE WISE EVERY STUDENT'
);
