 p_id=>wwv_flow_imp.id(30767317349012546304)
,p_event_id=>wwv_flow_imp.id(30767317245935546303)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'Get Student ID ON ACTIVE/INACTIVE'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_MAX_STUDENT_ID NUMBER;',
'   V_STUDENT VARCHAR2(20);',
'   V_STUDENT_ID NUMBER;',
'   BEGIN',
'       SELECT COUNT(*) INTO V_STUDENT',
'          FROM STUDENTS S',
'         WHERE S.STUDENT_ID = :P30_STUDENT_ID_1',
'           AND S.SITE_ID    = :APP_SITE_ID',
'           --AND S.STATUS    <> ''P''',
'           ;',
'          IF V_STUDENT = 0 AND :P30_STATUS <> ''P'' THEN',
'             SELECT NVL(MAX(STUDENT_ID),100)+1 INTO V_MAX_STUDENT_ID',
'             FROM STUDENTS S',
'            WHERE S.SITE_ID=:APP_SITE_ID ',
'              AND S.STATUS <> ''P''',
'              ;',
'            :P30_STUDENT_ID_1:=V_MAX_STUDENT_ID;    ',
'         ELSIF V_STUDENT = 0 AND :P30_STATUS = ''P'' THEN     ',
'            SELECT NVL(MAX(STUDENT_ID),0)+1 INTO V_MAX_STUDENT_ID',
'             FROM STUDENTS S',
'            WHERE S.SITE_ID=:APP_SITE_ID ',
'              AND S.STATUS = ''P''',
'              ;',
'            :P30_STUDENT_ID_1:=V_MAX_STUDENT_ID;    ',
'        END IF;   ',
'END;  '))
,p_attribute_02=>'P30_STUDENT_ID_1,P30_FEE_STATUS,P30_CLASS_ID'
,p_attribute_03=>'P30_STUDENT_ID_1'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_da_action_comment=>'pehly stage k hisab sy lag rahi thi student id ab sequence lag gya ha ab k g or a wala seen khatam ho gya ha or pending ki surat me p b khatam ho gy aha is liye is ko rok dia ha.'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(51530279598751594113)
,p_event_id=>wwv_flow_imp.id(30767317245935546303)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_name=>'Pass Inactive Date'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_ACTIVE_DATE DATE;',
'  V_INACTIVE_DATE DATE;',
'BEGIN',
'          BEGIN',
'          SELECT ACTIVE_DATE,INACTIVE_DATE INTO V_ACTIVE_DATE,V_INACTIVE_DATE',
'            FROM STUDENTS S     ',
'           WHERE S.STUDENT_ID=:P30_STUDENT_ID_1',
'             AND S.SITE_ID   =:APP_SITE_ID',
'             ;',
'         EXCEPTION WHEN NO_DATA_FOUND THEN',
'                 V_ACTIVE_DATE:='''';',
'                 V_INACTIVE_DATE:='''';',
'         END;         ',
'        IF :P30_STATUS = ''I'' THEN',
'            :P30_INACTIVE_DATE:=TRUNC(SYSDATE);',
'            :P30_ACTIVE_DATE  :=V_ACTIVE_DATE;',
'        ELSIF :P30_STATUS = ''A'' THEN',
'            --:P30_INACTIVE_DATE:='''';',
'            :P30_ACTIVE_DATE:=V_ACTIVE_DATE;',
'            :P30_INACTIVE_DATE:=V_INACTIVE_DATE;',
'        ELSIF :P30_STATUS = ''P'' THEN',
'            --:P30_INACTIVE_DATE:='''';',
'            :P30_ACTIVE_DATE:=TRUNC(SYSDATE);',
'            :P30_INACTIVE_DATE:=V_INACTIVE_DATE;    ',
'        END IF;   ',
'END;   '))
,p_attribute_02=>'P30_FEE_STATUS,P30_STUDENT_ID_1'
,p_attribute_03=>'P30_INACTIVE_DATE,P30_ACTIVE_DATE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
