,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_PLAN_BOOK_FEE NUMBER;',
'BEGIN',
'    BEGIN',
'        SELECT F.BOOKS_FEE ',
'          INTO V_PLAN_BOOK_FEE',
'          FROM FEE_PLAN F',
'         WHERE F.CLASS_ID = :P30_CLASS_ID',
'           AND F.SITE_ID  = :APP_SITE_ID',
'           AND F.STATUS   = ''A'';',
'    EXCEPTION ',
'        WHEN NO_DATA_FOUND THEN',
'            V_PLAN_BOOK_FEE := 0;',
'    END;',
'    :P30_BOOK_FEE := ROUND((V_PLAN_BOOK_FEE*:P30_NO_OF_BOOKS) - (((V_PLAN_BOOK_FEE*:P30_NO_OF_BOOKS) / 100) * NVL(:P30_BOOKS_FEE_DISC,0)),2);',
'',
'    :P30_TOTAL_PAYABLE:=NVL(:P30_REGISTRATION_FEE,0)+NVL(:P30_BOOK_FEE,0)+NVL(:P30_PAST_PAPER_FEE,0)+NVL(:P30_TOTAL_FEE,0);',
'END;',
''))
,p_attribute_02=>'P30_CLASS_ID,P30_BOOKS_FEE_DISC,P30_NO_OF_BOOKS,P30_REGISTRATION_FEE,P30_BOOK_FEE,P30_PAST_PAPER_FEE,P30_TOTAL_FEE'
,p_attribute_03=>'P30_BOOK_FEE,P30_TOTAL_PAYABLE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
