,p_process_name=>'Student Assessment Result - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
' BEGIN',
'    CASE :apex$row_status',
'      WHEN ''C'' THEN',
'      -- IF :SUBJECT_ID IS NOT NULL OR :SCORE IS NOT NULL THEN',
'          INSERT INTO STUDENT_ADMISSION_TEST(STUDENT_ID,TEST_DATE,CLASS_ID,SUBJECT_ID,BOOK_ID,TOTAL_MARKS,OBTAINED_MARKS,SCORE,GRADE,SITE_ID,FEED_BY,FEED_DATE)',
'            VALUES(:P30_STUDENT_ID_1,:TEST_DATE,:CLASS_ID,:SUBJECT_ID,:BOOK_ID,:TOTAL_MARKS,:OBTAINED_MARKS,:SCORE,:GRADE,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE))',
'            ;',
'       --END IF;     ',
'        WHEN ''U'' THEN',
'        -- IF :SUBJECT_ID IS NOT NULL OR :SCORE IS NOT NULL THEN',
'            UPDATE STUDENT_ADMISSION_TEST',
'            SET TEST_DATE            =:TEST_DATE,',
'                CLASS_ID             =:CLASS_ID,',
'                SUBJECT_ID           =:SUBJECT_ID,',
'                BOOK_ID              =:BOOK_ID,',
'                TOTAL_MARKS          =:TOTAL_MARKS,',
'                OBTAINED_MARKS       =:OBTAINED_MARKS,',
'                SCORE                =:SCORE,',
'                GRADE                =:GRADE,',
'                FEED_BY              =:APP_USER,',
'                FEED_DATE            =TRUNC(SYSDATE)',
'            WHERE TEST_ID            = :TEST_ID    ',
'            ;',
'         -- END IF;   ',
'        WHEN ''D'' THEN',
'            DELETE FROM STUDENT_ADMISSION_TEST',
'            WHERE TEST_ID   = :TEST_ID    ',
'            ;    ',
'    END CASE;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
