wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(52380902284234680674)
,p_name=>'Generate Stage '
,p_event_sequence=>20
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P31_CLASS_ID'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(77995140669375684403)
,p_event_id=>wwv_flow_imp.id(52380902284234680674)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P31_CLASS_ID IS NOT NULL THEN',
'     SELECT ',
'           CASE ',
'              WHEN year_number BETWEEN 1 AND 8  THEN ''K''',
'              WHEN year_number BETWEEN 9 AND 11 THEN ''G''',
'              WHEN year_number BETWEEN 12 AND 13 THEN ''A''',
'              ELSE NULL',
'           END AS STAGE INTO :P31_STAGE',
'      FROM   CLASSES',
'      WHERE  CLASS_ID = :P31_CLASS_ID',
'      ;',
'END IF',
';'))
,p_attribute_02=>'P31_CLASS_ID'
,p_attribute_03=>'P31_STAGE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(52380902718717680674)
,p_event_id=>wwv_flow_imp.id(52380902284234680674)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   V_MAX_STUDENT_ID NUMBER;',
'   V_CLASS_STAGE VARCHAR2(1);',
'  BEGIN',
'  IF :P31_CLASS_ID IS NOT NULL THEN',
'     SELECT SUBSTR(STAGE_TYPE,1,1) INTO V_CLASS_STAGE',
'       FROM CLASSES',
'      WHERE CLASS_ID=:P31_CLASS_ID',
'      ;  ',
'      IF V_CLASS_STAGE=''K'' THEN',
'        SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),300)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'           AND S.SITE_ID=:APP_SITE_ID ',
'        ;',
'      ELSIF V_CLASS_STAGE=''G'' THEN',
'           SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),500)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'           AND S.SITE_ID=:APP_SITE_ID ',
'         ;',
'      ELSIF V_CLASS_STAGE=''A'' THEN',
'           SELECT NVL(MAX(SUBSTR(STUDENT_ID,2)),100)+1 INTO V_MAX_STUDENT_ID',
'          FROM STUDENTS S',
'         WHERE V_CLASS_STAGE=SUBSTR(STUDENT_ID,1,1)',
'           AND S.SITE_ID=:APP_SITE_ID ',
'     ;       ',
'    END IF;',
'       :P31_STUDENT_ID:=V_CLASS_STAGE||V_MAX_STUDENT_ID;',
' END IF; ',
'END;  '))
,p_attribute_02=>'APP_SITE_ID,P31_CLASS_ID'
,p_attribute_03=>'P31_STUDENT_ID'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
);
