wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(51530279868097594116)
,p_event_id=>wwv_flow_imp.id(51530279789606594115)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_INACTIVE_DATE DATE;',
'  V_ACTIVE_DATE DATE;',
'BEGIN',
'  SELECT INACTIVE_DATE,ACTIVE_DATE INTO V_INACTIVE_DATE,V_ACTIVE_DATE',
'    FROM STUDENTS S     ',
'   WHERE S.STUDENT_ID=:P31_STUDENT_ID',
'     AND S.SITE_ID   =:APP_SITE_ID',
'     ; ',
'    IF :P31_STATUS <> ''I'' THEN',
'      :P31_INACTIVE_DATE:=V_INACTIVE_DATE;',
'      :P31_ACTIVE_DATE  :=TRUNC(SYSDATE);',
'    ELSIF V_INACTIVE_DATE IS NOT NULL AND :P31_STATUS = ''I'' THEN',
'         :P31_INACTIVE_DATE:=  V_INACTIVE_DATE;',
'         :P31_ACTIVE_DATE  :=V_ACTIVE_DATE;',
'    END IF;',
'END;'))
,p_attribute_02=>'P31_STATUS,P31_STUDENT_ID,APP_SITE_ID'
,p_attribute_03=>'P31_INACTIVE_DATE,P31_ACTIVE_DATE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
