wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(51243069848078517826)
,p_plug_name=>'ATTENDANCE REPORT'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  Z.DT,',
'  Z.ATTENDANCE_DATE,',
'  Z.STUDENT_ID,',
'  Z.STUDENT_NAME,',
'  Z.ATTENDANCE_STATUS,',
'  Z.REMARKS,',
'  C.WEEKDAY,',
'  C.START_TIME,',
'  C.END_TIME',
'FROM (',
'    SELECT',
'      TO_CHAR(A.dt, ''DD-MON-YYYY'') AS DT,',
'      B.ATTENDANCE_DATE,',
'      B.STUDENT_ID,',
'      B.STUDENT_NAME,',
'      B.ATTENDANCE_STATUS,',
'      B.REMARKS,',
'      B.WEEKDAY,',
'      B.START_TIME,',
'      B.END_TIME',
'    FROM (',
'        SELECT TO_DATE(TO_CHAR(SYSDATE, ''YYYY-MM'') || ''-'' || LEVEL, ''YYYY-MM-DD'') AS dt',
'        FROM dual',
'        CONNECT BY LEVEL <= TO_NUMBER(TO_CHAR(LAST_DAY(SYSDATE), ''DD''))',
'    ) A,',
'    (',
'        SELECT ',
'            SA.ATTENDANCE_DATE,',
'            ST.STUDENT_ID,',
'            ST.STUDENT_NAME || '' '' || ST.LAST_NAME AS STUDENT_NAME,',
'            SA.WEEKDAY,',
'            SA.START_TIME,',
'            SA.END_TIME,',
'            DECODE(SA.ATTENDANCE_STATUS, ''P'', ''Present'', ''A'', ''Absent'') AS ATTENDANCE_STATUS,',
'            SA.REMARKS',
'        FROM STUDENT_ATTENDANCE SA',
'        LEFT JOIN STUDENTS ST ON SA.STUDENT_ID = ST.STUDENT_ID AND SA.SITE_ID = ST.SITE_ID',
'        WHERE SA.SITE_ID = :APP_SITE_ID',
'          AND SA.STUDENT_ID = ''G519''',
'          AND TO_CHAR(SA.ATTENDANCE_DATE, ''MM-YYYY'') = NVL(TO_CHAR(TO_DATE(:P71_MONTH, ''MM-YYYY''), ''MM-YYYY''), TO_CHAR(SA.ATTENDANCE_DATE, ''MM-YYYY''))',
'          AND SA.STUDENT_ID = NVL(:P71_ADMISSION_NO, SA.STUDENT_ID)',
'          AND (SA.ATTENDANCE_STATUS IS NULL OR SA.ATTENDANCE_STATUS = NVL(:P71_ATTENDANCE_STATUS, SA.ATTENDANCE_STATUS))',
'    ) B',
'    WHERE A.dt = B.ATTENDANCE_DATE(+)',
') Z',
'LEFT JOIN (',
'    SELECT DISTINCT WEEKDAY, START_TIME, END_TIME',
'    FROM CLASS_SCHEDULE',
'    WHERE SITE_ID = :APP_SITE_ID',
') C',
'ON UPPER(TRIM(NVL(Z.WEEKDAY, TO_CHAR(TO_DATE(Z.DT, ''DD-MON-YYYY''), ''DAY'', ''NLS_DATE_LANGUAGE = ENGLISH'')))) = UPPER(TRIM(C.WEEKDAY))',
'  AND Z.START_TIME = C.START_TIME',
'  AND Z.END_TIME = C.END_TIME',
'ORDER BY Z.DT, C.START_TIME',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'ATTENDANCE REPORT'
);
