,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Role To Branch'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P38_SITE_ID IS NOT NULL THEN',
'      DELETE FROM ASSIGN_ROLE_BRANCH',
'            WHERE ROLE_ID=:P38_ROLE_ID',
'              AND SITE_ID NOT IN (SELECT REGEXP_SUBSTR(:P38_SITE_ID, ''[^:]+'', 1, LEVEL) AS V_CNT',
'                                    FROM DUAL',
'                                    CONNECT BY REGEXP_SUBSTR(:P38_SITE_ID, ''[^:]+'', 1, LEVEL) IS NOT NULL)',
'       ;',
'                                                                     ',
'    INSERT INTO ASSIGN_ROLE_BRANCH(ROLE_ID,SITE_ID,FEED_BY,FEED_DATE)',
'         SELECT :P38_ROLE_ID,V_CNT,:app_user,trunc(sysdate)',
'         FROM ASSIGN_ROLE_BRANCH U,(SELECT REGEXP_SUBSTR(:P38_SITE_ID, ''[^:]+'', 1, LEVEL) AS V_CNT',
'                                   FROM DUAL',
'                                   CONNECT BY REGEXP_SUBSTR(:P38_SITE_ID, ''[^:]+'', 1, LEVEL) IS NOT NULL)R',
'         WHERE U.ROLE_ID(+)=:P38_ROLE_ID',
'         AND   U.SITE_ID(+)  =R.V_CNT',
'         AND   U.SITE_ID IS NULL',
'         ;',
'ELSIF :P38_SITE_ID IS NULL THEN     ',
'     DELETE FROM ASSIGN_ROLE_BRANCH',
'        WHERE ROLE_ID=:P38_ROLE_ID',
'        ;',
' END IF;       '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Branches assign to role.'
,p_internal_uid=>58716239215819495376
);
