'select STUDENT_ID STUDENT_NO,',
'       STAGE||''-''||STUDENT_ID STUDENT_ID,',
'       STUDENT_NAME||'' ''||LAST_NAME Student_Name,',
'       DECODE(GENDER,''M'',''Male'',''F'',''Female'')GENDER,',
'       TO_CHAR(DATE_OF_BIRTH,''DD-MON-YYYY'')DATE_OF_BIRTH,',
'       TO_CHAR(ADMISSION_DATE,''DD-MON-YYYY'')ADMISSION_DATE,',
'       CLASS_ID,',
'       SESSIONS,',
'       SITE_ID,',
'       DECODE(STATUS,''A'',''Active'',''I'',''In-Active'')STATUS  ',
'  from STUDENTS S',
'  WHERE S.STATUS=''I''',
'    AND S.SITE_ID=:APP_SITE_ID',
'    AND S.STUDENT_ID=NVL(:P41_STUDENT_LIST,S.STUDENT_ID)',
'    ORDER BY CASE',
'            WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'            WHEN STUDENT_ID LIKE ''G%'' THEN 2',
