wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(19262599677857911584)
,p_name=>'Assign Teacher'
,p_template=>4072358936313175081
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select T.ASSIGN_ID,',
'       T.EMP_ID,',
'       E.EMP_NAME||'' ''||E.LAST_NAME EMP_NAME,',
'       STS.STAGE||''-''||T.STUDENT_ID STUDENT_ID,',
'       STS.STUDENT_NAME||'' ''||STS.LAST_NAME STUDENT_NAME,',
'       ST.SITE_NAME BRANCH,',
'       S.CLASS_ID,',
'       CS.CLASS_NAME,',
'       B.BOOK_NAME BOOK,',
'       S.SUBJECT_ID,',
'       SS.SUBJECT_NAME SUBJECT,',
'       CLS.WEEKDAY,',
'       CLS.START_TIME,',
'       CLS.END_TIME,',
'       T.ASSIGN_DATE,',
'       T.STATUS,',
'       T.FEED_BY,',
'       T.FEED_DATE',
'  from TEACHER_ASSIGN_TO_STUDENT T,STUDENT_CLASSES_SCHEDULE S,EMPLOYEES E,SITES ST,CLASSES CS,CLASS_SCHEDULE CLS,BOOKS B,SUBJECTS SS,STUDENTS STS',
'  WHERE T.STUDENT_CLASS_SCHEDULE_ID = S.STUDENT_SCHEDULE_ID',
'    AND T.SITE_ID                   = S.SITE_ID',
'    AND T.EMP_ID                    = E.EMP_ID',
'    AND T.SITE_ID                   = ST.SITE_ID',
'    AND T.CLASS_ID                  = CS.CLASS_ID',
'    AND S.CLASS_SHEDULE_ID          = CLS.SCHEDULE_ID',
'    AND S.SITE_ID                   = CLS.SITE_ID',
'    AND S.BOOK_ID                   = B.BOOK_ID(+)',
'    AND S.SUBJECT_ID                = SS.SUBJECT_ID',
'    AND T.STUDENT_ID                = STS.STUDENT_ID',
'    AND T.SITE_ID                   = STS.SITE_ID',
'    AND T.STATUS                    = ''A''',
'    AND S.STATUS                    = ''A''',
'    AND CS.STATUS                   = ''A''',
'    AND STS.STATUS                  = ''A''',
'    AND T.SITE_ID                   = :APP_SITE_ID',
'    AND T.EMP_ID                    = NVL(:P42_EMPLOYEE_ID,T.EMP_ID)    ',
'    AND T.STUDENT_ID                = NVL(:P42_STUDENT_ID,T.STUDENT_ID)   ',
'    AND S.SUBJECT_ID                = NVL(:P42_SUBJECT,S.SUBJECT_ID)',
'    AND NVL(S.BOOK_ID,0)            = NVL(:P42_BOOK,NVL(S.BOOK_ID,0))',
'    AND UPPER(CLS.WEEKDAY)          = NVL(UPPER(:P42_WEEKDAY),UPPER(CLS.WEEKDAY))',
'    ORDER BY ASSIGN_ID DESC',
';'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P42_EMPLOYEE_ID,P42_STUDENT_ID,P42_SUBJECT,P42_BOOK,P42_WEEKDAY'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>50
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'no data found'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>500
,p_pagination_display_position=>'BOTTOM_RIGHT'
