,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlight:t-Report--inline:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select STUDENT_SCHEDULE_ID,',
'       STU.STAGE||''-''||S.STUDENT_ID AS ADMISSION_NO,',
'       S.CLASS_ID,',
'       CS.CLASS_NAME,',
'       CL.CLASS_NAME AS STUDENT_YEAR,',
'       S.SUBJECT_ID,',
'       SB.SUBJECT_NAME,',
'       S.BOOK_ID,',
'       B.BOOK_NAME,',
'       C.WEEKDAY,',
'       C.START_TIME,',
'       C.END_TIME,',
'       CLASS_SHEDULE_ID,',
'       DECODE(S.STATUS,''A'',''Active'',''I'',''In-Active'')STATUS,',
'       S.FEED_BY,',
'       S.FEED_DATE,',
'       S.SITE_ID',
'  from STUDENT_CLASSES_SCHEDULE S,CLASS_SCHEDULE C,SUBJECTS SB,BOOKS B,CLASSES CS, CLASSES CL,STUDENTS STU',
' where S.CLASS_SHEDULE_ID= C.SCHEDULE_ID',
'   AND S.STUDENT_ID      = STU.STUDENT_ID',
'   AND S.SITE_ID         = STU.SITE_ID',
'   AND S.SITE_ID         = C.SITE_ID',
'   AND S.SUBJECT_ID      = SB.SUBJECT_ID',
'   AND S.BOOK_ID         = B.BOOK_ID(+)',
'   AND S.CLASS_ID        = CS.CLASS_ID',
'   AND STU.CLASS_ID      = CL.CLASS_ID',
'   AND S.STATUS          = ''I''',
'   AND S.SITE_ID         = :P47_BRANCHES',
'   AND S.STUDENT_ID      = NVL(:P47_STUDENT_ID,S.STUDENT_ID)',
'   ORDER BY S.STUDENT_ID,TO_DATE(C.START_TIME, ''HH24:MI'') ASC'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P47_BRANCHES,P47_STUDENT_ID'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
