wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(83974167881021534903)
,p_name=>'Siblings'
,p_parent_plug_id=>wwv_flow_imp.id(111746706151967620790)
,p_template=>4072358936313175081
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--scrollBody:margin-top-none:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    sb.stage||''-''||sb.STUDENT_ID       AS SIBLING_ID,',
'    sb.STUDENT_NAME||'' ''||SB.LAST_NAME     AS SIBLING_NAME,',
'    C.CLASS_NAME         AS SIBLING_CLASS,',
'    P.PARENT_NAME,',
'    DECODE(sb.GENDER,''M'',''Male'',''F'',''Female'') AS SIBLING_GENDER,',
'    sb.stage',
'',
'FROM STUDENTS ms',
'JOIN STUDENTS sb',
'  ON sb.site_id = ms.site_id',
'JOIN CLASSES C',
'  ON SB.CLASS_ID = C.CLASS_ID',
'JOIN STUDENT_PARENTS P',
'  ON SB.STUDENT_ID = P.STUDENT_ID ',
'  AND SB.SITE_ID   = P.SITE_ID',
' AND sb.student_id IN (',
'        SELECT student_id',
'        FROM STUDENTS',
'        START WITH student_id = NVL(:P48_STUDENT_ID_1, ms.student_id)',
'                 AND site_id = :APP_SITE_ID',
'        CONNECT BY NOCYCLE',
'          (PRIOR student_id = sibling_ad_no OR PRIOR sibling_ad_no = student_id)',
'          AND PRIOR site_id = site_id',
'     )',
' AND sb.student_id <> ms.student_id   -- exclude main student',
'',
'WHERE ms.site_id = :APP_SITE_ID',
'  AND ms.student_id = :P48_STUDENT_ID_1 ',
