,p_execute_on_page_init=>'N'
,p_name=>'Pass Inactive Date'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_ACTIVE_DATE DATE;',
'  V_INACTIVE_DATE DATE;',
'BEGIN',
'     BEGIN',
'      SELECT ACTIVE_DATE,INACTIVE_DATE INTO V_ACTIVE_DATE,V_INACTIVE_DATE',
'        FROM STUDENTS S     ',
'       WHERE S.STUDENT_ID=:P48_STUDENT_ID_1',
'         AND S.SITE_ID   =:APP_SITE_ID',
'         ;',
'     EXCEPTION WHEN NO_DATA_FOUND THEN',
'             V_ACTIVE_DATE:='''';',
'             V_INACTIVE_DATE:='''';',
'     END;         ',
'    IF :P48_STATUS = ''I'' THEN',
'        :P48_INACTIVE_DATE:=TRUNC(SYSDATE);',
'        :P48_ACTIVE_DATE  :=V_ACTIVE_DATE;',
'    ELSE',
'        --:P48_INACTIVE_DATE:='''';',
'        :P48_ACTIVE_DATE:=V_ACTIVE_DATE;',
'        :P48_INACTIVE_DATE:=V_INACTIVE_DATE;',
'    END IF;',
'END;    '))
,p_attribute_02=>'P48_STATUS,P48_STUDENT_ID_1'
,p_attribute_03=>'P48_INACTIVE_DATE,P48_ACTIVE_DATE'
,p_attribute_04=>'N'
