,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_EXAM_FEE NUMBER;',
'  V_PAST_PAPER_FEE NUMBER;',
'  V_REG_FEE NUMBER;',
'  V_BOOK_FEE NUMBER;',
'BEGIN    ',
'    SELECT COUNT(*) INTO V_EXAM_FEE',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.EXAM_FEE IS NOT NULL',
'       ; ',
'    SELECT COUNT(*) INTO V_PAST_PAPER_FEE',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.PAST_PAPER_FEE IS NOT NULL',
'       ; ',
'    SELECT COUNT(*) INTO V_REG_FEE',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.REGISTRATION_FEE IS NOT NULL',
'       ;',
'    SELECT COUNT(*) INTO V_BOOK_FEE',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.BOOKS_FEE IS NOT NULL',
'       ;           ',
'  IF V_EXAM_FEE = 0 THEN',
'  BEGIN',
'    SELECT EXAM_FEE INTO :P49_EXAM_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       --AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'    :P49_EXAM_FEE        :=0;',
'     END;',
'  END IF',
'  ;',
' IF V_PAST_PAPER_FEE = 0 THEN',
'  BEGIN',
'    SELECT PAST_PAPER_FEE INTO :P49_PAST_PAPER_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'      -- AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'    :P49_PAST_PAPER_FEE:=0;',
'     END;',
'  END IF',
'  ;',
'   IF V_REG_FEE = 0 THEN',
'  BEGIN',
'    SELECT REGISTRATION_FEE INTO :P49_REGISTRATION_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'      -- AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'    :P49_REGISTRATION_FEE:=0;',
'     END;',
'  END IF',
'  ;',
'    IF V_BOOK_FEE = 0 THEN',
'  BEGIN',
'    SELECT BOOK_FEE INTO :P49_BOOK_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'      -- AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'    :P49_BOOK_FEE:=0;',
'     END;',
'  END IF',
'  ;',
'END;      ',
'',
''))
,p_attribute_02=>'P49_STUDENT_ID,APP_SITE_ID'
,p_attribute_03=>'P49_REGISTRATION_FEE,P49_EXAM_FEE,P49_PAST_PAPER_FEE,P49_BOOK_FEE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
