,p_event_id=>wwv_flow_imp.id(21769941772856508719)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_PAY_COOUNT NUMBER;',
'  V_CNT NUMBER;',
'  V_REG_FEE NUMBER:=0;',
'  V_EXAM_FEE NUMBER:=0;',
'  V_PAST_PAPER_FEE NUMBER:=0;',
'  V_BOOK_FEE NUMBER:=0;',
'  V_EXAM_FEE1 NUMBER;',
'  V_PAST_PAPER_FEE1 NUMBER;',
'  V_REG_FEE1 NUMBER;',
'  V_BOOK_FEE1 NUMBER;',
'BEGIN  ',
'  BEGIN',
'      SELECT NVL(MAX(PAYMENT_COUNT),0)+1 INTO V_PAY_COOUNT',
'        FROM STUDENT_FEE_COLLECTION C   ',
'       WHERE C.STUDENT_ID=:P49_STUDENT_ID',
'         AND C.SITE_ID  =:APP_SITE_ID',
'         AND C.FEE_MONTH=:P49_FEE_MONTH  ',
'         ;',
'     EXCEPTION WHEN NO_DATA_FOUND THEN',
'         V_PAY_COOUNT:=1;',
'     END',
'     ;      ',
'BEGIN    ',
'    SELECT COUNT(*) INTO V_EXAM_FEE1',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.EXAM_FEE IS NOT NULL',
'       ; ',
'    SELECT COUNT(*) INTO V_PAST_PAPER_FEE1',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.PAST_PAPER_FEE IS NOT NULL',
'       ; ',
'    SELECT COUNT(*) INTO V_REG_FEE1',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.REGISTRATION_FEE IS NOT NULL',
'       ;',
'    SELECT COUNT(*) INTO V_BOOK_FEE1',
'      FROM STUDENT_FEE_COLLECTION S    ',
'     WHERE S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       AND S.BOOKS_FEE IS NOT NULL',
'       ;           ',
'  IF V_EXAM_FEE1 = 0 THEN',
'  BEGIN',
'    SELECT EXAM_FEE INTO V_EXAM_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'      -- AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'       V_EXAM_FEE:=0;',
'     END;',
'  END IF',
'  ;',
' IF V_PAST_PAPER_FEE1 = 0 THEN',
'  BEGIN',
'    SELECT PAST_PAPER_FEE INTO V_PAST_PAPER_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'       --AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'     V_PAST_PAPER_FEE:=0;',
'     END;',
'  END IF',
'  ;',
'   IF V_REG_FEE1 = 0 THEN',
'  BEGIN',
'    SELECT REGISTRATION_FEE INTO V_REG_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'      -- AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'     V_REG_FEE:=0;',
'     END;',
'  END IF',
'  ;',
'    IF V_BOOK_FEE1 = 0 THEN',
'  BEGIN',
'    SELECT BOOK_FEE INTO V_BOOK_FEE',
'      FROM STUDENTS S,STUDENT_FEES F',
'     WHERE S.STUDENT_ID=F.STUDENT_ID    ',
'       AND S.SITE_ID   =F.SITE_ID',
'       AND S.STUDENT_ID=:P49_STUDENT_ID',
'       AND S.SITE_ID=:APP_SITE_ID',
'      -- AND S.STATUS=''A''',
'     ;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'      V_BOOK_FEE:=0;',
'     END;',
'  END IF',
'  ;',
'END',
';        ',
'    IF V_PAY_COOUNT = 1 THEN',
'       :P49_PAYABLE_FEE:=NVL(:P49_MONTHLY_FEE,0)+NVL(:P49_OPENING_BALANCE,0)+NVL(V_EXAM_FEE,0)+NVL(V_PAST_PAPER_FEE,0)+NVL(:P49_DISCOUNT,0)+NVL(V_REG_FEE,0)+NVL(V_BOOK_FEE,0);',
'    ELSE ',
'       :P49_PAYABLE_FEE:=NVL(:P49_OPENING_BALANCE,0)+NVL(V_EXAM_FEE,0)+NVL(V_PAST_PAPER_FEE,0)+NVL(:P49_DISCOUNT,0)+NVL(V_REG_FEE,0)+NVL(V_BOOK_FEE,0);',
'    END IF;  ',
'END;'))
,p_attribute_02=>'P49_OPENING_BALANCE,P49_DISCOUNT,P49_MONTHLY_FEE,P49_EXAM_FEE,P49_PAST_PAPER_FEE,P49_RECEIVED_AMOUNT,P49_REGISTRATION_FEE,P49_STUDENT_ID,P49_FEE_MONTH'
,p_attribute_03=>'P49_PAYABLE_FEE,P49_CLOSING_BALANACE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
