,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "ASSESSMENT_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P50_ASSESSMENT_ID'', p_values => "ASSESSMENT_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P50_ASSESSMENT_ID,''0'') = "ASSESSMENT_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'     (substr("ASSESSMENT_ID", 1, 50)||( case when length("ASSESSMENT_ID") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("FIRST_NAME", 1, 50)||( case when length("FIRST_NAME") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "STUDENT_ASSESSMENT" x',
'where (:P50_SEARCH is null',
'        or upper(x."ASSESSMENT_ID") like ''%''||upper(:P50_SEARCH)||''%''',
'        or upper(x."FIRST_NAME") like ''%''||upper(:P50_SEARCH)||''%''',
'    )',
' AND SITE_ID=:APP_SITE_ID   ',
'order by ASSESSMENT_ID DESC'))
,p_ajax_enabled=>'Y'
