,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select SCR.ROWID,',
'       SCR.RESCHEDULING_ID,',
'       SCR.RESHEDULE_DATE,',
'       SCR.EMPLOYEE_ID,',
'       E.EMP_NAME||'' ''||E.LAST_NAME EMP_NAME,',
'       SCR.STUDENT_ID,',
'       S.STUDENT_NAME||'' ''||S.LAST_NAME STUDENT_NAME,',
'       SCR.CLASS_ID,',
'       C.CLASS_NAME,',
'       SCR.SUBJECT_ID,',
'       SB.SUBJECT_NAME,',
'       SCR.BOOK_ID,',
'       B.BOOK_NAME,',
'       CLASS_SHEDULE_ID,',
'       CS.WEEKDAY,',
'       CS.START_TIME,',
'       CS.END_TIME,',
'       SCR.SITE_ID,',
'       SCR.STATUS',
'  from STUDENT_CLASS_RESCHEDULING SCR,STUDENTS S,CLASSES C,CLASS_SCHEDULE CS,SUBJECTS SB,BOOKS B,EMPLOYEES E',
'  WHERE SCR.STUDENT_ID = S.STUDENT_ID',
'    AND SCR.SITE_ID    = S.SITE_ID',
'    AND SCR.CLASS_ID   = C.CLASS_ID',
'    AND SCR.CLASS_SHEDULE_ID=CS.SCHEDULE_ID',
'    AND SCR.SITE_ID    = CS.SITE_ID',
'    AND SCR.SUBJECT_ID = SB.SUBJECT_ID',
'    AND SCR.BOOK_ID    = B.BOOK_ID(+)',
'    AND SCR.EMPLOYEE_ID= E.EMP_ID(+)',
'    AND SCR.SITE_ID    = :APP_SITE_ID',
'    AND SCR.EMPLOYEE_ID= NVL(:P56_EMPLOYEE_ID,SCR.EMPLOYEE_ID)    ',
'    AND SCR.STUDENT_ID = NVL(:P56_STUDENT_ID,SCR.STUDENT_ID)   ',
'    AND SCR.SUBJECT_ID = NVL(:P56_SUBJECT,SCR.SUBJECT_ID)',
'    AND NVL(SCR.BOOK_ID,0)= NVL(:P56_BOOK,NVL(SCR.BOOK_ID,0))',
'    AND UPPER(CS.WEEKDAY)= NVL(UPPER(:P56_WEEKDAY),UPPER(CS.WEEKDAY))',
'    AND SCR.STATUS       = ''A''',
'    AND CS.STATUS        = ''A''',
'    AND S.STATUS         = ''A''',
'    ORDER BY RESCHEDULING_ID DESC',
'                                          ;',
''))
