wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(27683588187314788941)
,p_name=>'Total Fee'
,p_template=>2072724515482255512
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#:u-colors:t-BadgeList--xlarge:t-BadgeList--dash:t-BadgeList--flex:t-Report--hideNoPagination'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT TO_CHAR(ROUND((SUM(STUDENT_TOTAL_FEE))*SUM(TOTAL_MONTHS)), ''99,99,99,990'')STUDENT_TOTAL_FEE,TO_CHAR(ROUND(SUM(Received_Fee)), ''99,99,99,990'')Received_Fee,',
'       TO_CHAR((ROUND((SUM(STUDENT_TOTAL_FEE)*SUM(TOTAL_MONTHS))-SUM(Received_Fee))),''99,99,99,990'')OVER_ALL_PENDING,SUM(advance_Fee)advance_Fee,SUM(Pending_Fee)Pending_Fee',
'  FROM(',
'SELECT ',
'  NVL(SUM(S.TOTAL_FEE), 0) + NVL(SUM(S.REGISTRATION_FEE), 0) + NVL(SUM(S.EXAM_FEE), 0) + NVL(SUM(S.BOOK_FEE), 0) + NVL(SUM(S.PAST_PAPER_FEE), 0) STUDENT_TOTAL_FEE,',
'  0 Received_Fee,',
'  0 advance_Fee,',
'  0 Pending_Fee,',
'  TRUNC(MONTHS_BETWEEN(',
'  NVL(:P59_TO_DATE, SYSDATE),',
'  NVL(:P59_FROM_DATE, SYSDATE)',
')) + 1 AS TOTAL_MONTHS',
'FROM STUDENT_FEES S',
'JOIN STUDENTS ST ON ST.STUDENT_ID = S.STUDENT_ID AND ST.SITE_ID = S.SITE_ID',
'WHERE S.SITE_ID = :APP_SITE_ID',
'AND ST.ADMISSION_DATE <= NVL(:P59_TO_DATE, TRUNC(SYSDATE)) ',
'AND (ST.INACTIVE_DATE IS NULL OR ST.INACTIVE_DATE >= NVL(:P59_FROM_DATE, ST.ADMISSION_DATE))',
'UNION ALL ',
'SELECT /*NVL(TOTAL_FEE,0)TOTAL_FEE,*/0 STUDENT_TOTAL_FEE,NVL(Received_Fee,0)Received_Fee,ABS(NVL(advance_Fee,0))advance_Fee,NVL(Pending_Fee,0)Pending_Fee,',
'       0 TOTAL_MONTHS',
'FROM(',
'    SELECT NVL(SUM(TOTAL_FEE),0)TOTAL_FEE,NVL(SUM(Received_Fee),0)Received_Fee, NVL(SUM(advance_Fee),0)advance_Fee,NVL(SUM(Pending_Fee),0)Pending_Fee',
'    FROM(',
'    SELECT STUDENT_ID,(NVL(OPENING_BALANCE,0)+TOTAL_FEE)TOTAL_FEE,SUM(RCVD_AMT)Received_Fee,CASE WHEN NVL(CLOSING_BALANCE,0) < 0 THEN NVL(CLOSING_BALANCE,0) END AS advance_Fee,',
'          CASE WHEN NVL(CLOSING_BALANCE,0) > 0 THEN NVL(CLOSING_BALANCE,0) END AS Pending_Fee',
'    FROM(',
'    SELECT A.STUDENT_ID,A.FEE_MONTH,NVL(MONTHLY_FEE, 0) + NVL(SUM(A.REGISTRATION_FEE), 0) + NVL(SUM(A.DISCOUNT), 0) + NVL(SUM(A.EXAM_FEE), 0) + NVL(SUM(A.BOOKS_FEE), 0) + NVL(SUM(A.PAST_PAPER_FEE), 0) AS TOTAL_FEE,  ',
'           NVL(SUM(RECEIVED_AMOUNT), 0) RCVD_AMT, ',
'        (',
'            SELECT NVL(SOB.OPENING_BALANCE, 0)',
'            FROM STUDENT_FEE_COLLECTION SOB ',
'            WHERE SOB.STUDENT_ID = A.STUDENT_ID ',
'              AND SOB.SITE_ID = A.SITE_ID ',
'              AND SOB.FEE_MONTH = A.FEE_MONTH',
'              AND FEE_COLLECTION_ID = (',
'                  SELECT MIN(SFI.FEE_COLLECTION_ID) ',
'                  FROM STUDENT_FEE_COLLECTION SFI ',
'                  WHERE SFI.STUDENT_ID = A.STUDENT_ID ',
'                    AND SFI.SITE_ID = A.SITE_ID ',
'                    AND SFI.FEE_MONTH = A.FEE_MONTH',
'              )',
'        ) AS OPENING_BALANCE,',
'        (',
'            SELECT NVL(SOB.CLOSING_BALANCE, 0)',
'            FROM STUDENT_FEE_COLLECTION SOB ',
'            WHERE SOB.STUDENT_ID = A.STUDENT_ID ',
'              AND SOB.SITE_ID = A.SITE_ID ',
'              AND SOB.FEE_MONTH = A.FEE_MONTH',
'              AND FEE_COLLECTION_ID = (',
'                  SELECT MAX(SFI.FEE_COLLECTION_ID) ',
'                  FROM STUDENT_FEE_COLLECTION SFI ',
'                  WHERE SFI.STUDENT_ID = A.STUDENT_ID ',
'                    AND SFI.SITE_ID = A.SITE_ID ',
'                    AND SFI.FEE_MONTH = A.FEE_MONTH',
'              )',
'        ) AS CLOSING_BALANCE',
'',
'    FROM STUDENT_FEE_COLLECTION A, PAYMENT_TYPE P',
'    WHERE A.PAYMENT_METHOD = P.PAY_ID    ',
'      AND A.SITE_ID        = :P59_BRANCHES',
'      AND PAYMENT_DATE BETWEEN NVL(:P59_FROM_DATE, PAYMENT_DATE) AND NVL(:P59_TO_DATE, PAYMENT_DATE)',
'      AND TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') =NVL(TO_CHAR(TO_DATE(:P59_FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') ,TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY''))',
'    GROUP BY A.STUDENT_ID,A.SITE_ID,FEE_MONTH,MONTHLY_FEE',
'    )',
'    GROUP BY STUDENT_ID,TOTAL_FEE,OPENING_BALANCE,CLOSING_BALANCE',
'    )',
')   ',
')',
'',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P59_FROM_DATE,P59_TO_DATE,P59_FEE_MONTH,P59_BRANCHES'
,p_lazy_loading=>false
,p_query_row_template=>2104643962563030528
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
