,p_format_mask=>'MM-YYYY'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT TO_CHAR(ADD_MONTHS(start_month, LEVEL - 1), ''MON-YYYY'') AS MONTH_YEAR,TO_CHAR(ADD_MONTHS(start_month, LEVEL - 1), ''MM-YYYY'') ',
'FROM (',
'    SELECT CASE ',
'             WHEN TO_CHAR(SYSDATE, ''MM'') BETWEEN ''06'' AND ''12'' ',
'             THEN TO_DATE(''01-'' || TO_CHAR(SYSDATE, ''MM-YYYY''), ''DD-MM-YYYY'')',
'             ELSE TO_DATE(''01-01-'' || TO_CHAR(SYSDATE, ''YYYY''), ''DD-MM-YYYY'')',
'           END AS start_month',
'    FROM DUAL',
')',
'CONNECT BY LEVEL <= 13;'))
