 p_id=>wwv_flow_imp.id(105571470058196097381)
,p_plug_name=>'Student Attendance'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select SA.ATTENDANCE_DATE,SA.STUDENT_ID,ST.STUDENT_NAME||'' ''||ST.LAST_NAME STUDENT_NAME,',
'      C.CLASS_NAME,SA.WEEKDAY,S.SUBJECT_NAME,B.BOOK_NAME,SA.START_TIME,SA.END_TIME,DECODE(SA.ATTENDANCE_STATUS, ''P'',''Present'',''A'',''Absent'') AS ATTENDANCE_STATUS,SA.REMARKS',
'FROM STUDENT_ATTENDANCE SA,CLASSES C,SUBJECTS S,BOOKS B,STUDENTS ST',
'WHERE SA.CLASS_ID = C.CLASS_ID',
'AND SA.SUBJECT_ID = S.SUBJECT_ID',
'AND SA.BOOK_ID    = B.BOOK_ID',
'AND SA.STUDENT_ID =ST.STUDENT_ID',
'AND SA.SITE_ID    =ST.SITE_ID',
'AND SA.SITE_ID    =:APP_SITE_ID',
'AND SA.ATTENDANCE_DATE BETWEEN NVL(:P71_FROM_DATE,SA.ATTENDANCE_DATE) AND NVL(:P71_TO_DATE,SA.ATTENDANCE_DATE)',
'AND TO_CHAR(SA.ATTENDANCE_DATE, ''MM-YYYY'') = NVL(TO_CHAR(TO_DATE(:P71_MONTH, ''MM-YYYY''), ''MM-YYYY''), TO_CHAR(SA.ATTENDANCE_DATE, ''MM-YYYY''))',
'AND SA.STUDENT_ID=NVL(:P71_ADMISSION_NO,SA.STUDENT_ID)',
'AND SA.ATTENDANCE_STATUS=NVL(:P71_ATTENDANCE_STATUS,SA.ATTENDANCE_STATUS)',
'ORDER BY SA.ATTENDANCE_DATE DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P71_FROM_DATE,P71_TO_DATE,P71_ADMISSION_NO,P71_ATTENDANCE_STATUS,P71_MONTH'
,p_prn_content_disposition=>'ATTACHMENT'
