wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(30271370377131359727)
,p_plug_name=>'STUDENT_REPORT'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT ROWNUM,STUDENT_ID,STUDENT_NAME,GENDER,PARENT_NAME,ADMISSION_DATE,CLASS_NAME,STATUS,TOTAL_FEE,TOTAL_STUDY_HOURS',
'  FROM(  ',
'   SELECT S.STAGE||''-''||S.STUDENT_ID AS STUDENT_ID,',
'       S.STUDENT_NAME||'' ''||S.LAST_NAME AS STUDENT_NAME,',
'       S.STUDENT_TYPE,',
'       DECODE(S.GENDER,''M'',''Male'',''F'',''Female'') AS GENDER,',
'       P.PARENT_NAME,',
'       S.ADMISSION_DATE,',
'       C.CLASS_NAME,',
'       DECODE(S.STATUS, ''A'',''Active'',''I'',''In active'',''AR'',''Archive'',''AL'',''Alumni'')AS STATUS,',
'       F.TOTAL_FEE,',
'       NVL(SUM(',
'              CASE ',
'                WHEN CS.START_TIME IS NOT NULL ',
'                     AND CS.END_TIME IS NOT NULL',
'                     AND REGEXP_LIKE(CS.START_TIME, ''^\d{2}:\d{2}$'')',
'                     AND REGEXP_LIKE(CS.END_TIME, ''^\d{2}:\d{2}$'')',
'                THEN ROUND((TO_DATE(CS.END_TIME, ''HH24:MI'') - TO_DATE(CS.START_TIME, ''HH24:MI'')) * 24, 2)',
'                ELSE 0',
'              END',
'), 0) AS TOTAL_STUDY_HOURS',
'       --NVL(SUM( ROUND((TO_DATE(CS.END_TIME, ''HH24:MI'') - TO_DATE(CS.START_TIME, ''HH24:MI'')) * 24, 2)),0) TOTAL_STUDY_HOURS',
'FROM STUDENTS S, CLASSES C, STUDENT_PARENTS P,STUDENT_FEES F,STUDENT_CLASSES_SCHEDULE SCS,CLASS_SCHEDULE CS',
'WHERE S.CLASS_ID = C.CLASS_ID',
'AND S.STUDENT_ID = P.STUDENT_ID(+)',
'AND S.SITE_ID    = P.SITE_ID(+)',
'AND S.STUDENT_ID = F.STUDENT_ID(+)',
'AND S.SITE_ID    = F.SITE_ID(+)',
'AND S.STUDENT_ID =SCS.STUDENT_ID(+)',
'AND S.SITE_ID    =SCS.SITE_ID(+)',
'AND SCS.CLASS_SHEDULE_ID=CS.SCHEDULE_ID(+)',
'AND SCS.SITE_ID  =CS.SITE_ID(+)',
'AND S.SITE_ID    = :P72_BRANCHES',
'AND S.STUDENT_ID = NVL(:P72_ADMISSION_NO,S.STUDENT_ID)',
'AND S.STATUS     = NVL(:P72_STATUS,S.STATUS)',
'AND S.CLASS_ID = NVL(:P72_YEAR,S.CLASS_ID)',
'GROUP BY S.STUDENT_ID,S.STUDENT_NAME,S.LAST_NAME,S.STUDENT_TYPE,S.STAGE,S.GENDER,P.PARENT_NAME,S.ADMISSION_DATE,C.CLASS_NAME,S.STATUS,F.TOTAL_FEE',
'ORDER BY  CASE',
'            WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'            WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'            WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'          END,LENGTH(STUDENT_ID),STUDENT_ID',
'  )'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P72_YEAR,P72_ADMISSION_NO,P72_STATUS,P72_BRANCHES'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
