wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(33963820633555714822)
,p_validation_name=>'Stop resheduling in lesson plan'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'BEGIN',
'  SELECT COUNT(*) INTO V_CNT',
'    FROM STUDENT_CLASS_RESCHEDULING TA',
'   WHERE SUBJECT_ID         = :P73_SUBJECT_ID',
'     AND NVL(TA.BOOK_ID,0)  = NVL(:P73_BOOK_ID,0)',
'     AND TA.STUDENT_ID      = :P73_STUDENT_ID',
'     AND TA.SITE_ID         = :APP_SITE_ID',
'     AND TA.CLASS_SHEDULE_ID= :P73_CLASS_SHEDULE_ID',
'     --AND SCS.STATUS=''A''',
'     ;',
'     IF V_CNT > 0 THEN    ',
'        RETURN FALSE;',
'     ELSE',
'        RETURN TRUE;',
'     END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'This lesson plan already assign in catchup lesson plan, if you assign this please delete it from catchup lesson plan first.'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(39982862072043300529)
,p_validation_name=>'Stop duplicate in lesson plan ON INSERT'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'BEGIN',
'   SELECT COUNT(*) INTO V_CNT',
'     FROM STUDENT_CLASSES_SCHEDULE SC    ',
'    WHERE CLASS_SHEDULE_ID  = :P73_CLASS_SHEDULE_ID',
'      --AND SC.SUBJECT_ID     = :P73_SUBJECT_ID',
'      --AND NVL(SC.BOOK_ID,0) = NVL(:P73_BOOK_ID,0)',
'      AND SC.STUDENT_ID     = :P73_STUDENT_ID',
'      AND SC.SITE_ID        = :P73_SITE_ID',
'      ;   ',
'      IF V_CNT > 0 THEN',
'         RETURN FALSE; ',
'      ELSE',
'         RETURN TRUE;',
'      END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'This lesson plan schedule already assign.'
,p_when_button_pressed=>wwv_flow_imp.id(33936194413456440924)
