wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(77625081581330605107)
,p_validation_name=>'Stop duplicate in lesson plan ON UPDATE'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'  V_STATUS VARCHAR2(5);',
'BEGIN',
'   SELECT COUNT(*) INTO V_CNT',
'     FROM STUDENT_CLASSES_SCHEDULE SC    ',
'    WHERE CLASS_SHEDULE_ID  = :P73_CLASS_SHEDULE_ID',
'      --AND SC.SUBJECT_ID     = :P73_SUBJECT_ID',
'      --AND NVL(SC.BOOK_ID,0) = NVL(:P73_BOOK_ID,0)',
'      AND SC.STUDENT_ID     = :P73_STUDENT_ID',
'      AND SC.SITE_ID        = :P73_SITE_ID',
'      ;',
'   BEGIN   ',
'    SELECT STATUS INTO V_STATUS',
'     FROM STUDENT_CLASSES_SCHEDULE SC    ',
'    WHERE CLASS_SHEDULE_ID  = :P73_CLASS_SHEDULE_ID',
'      AND SC.SUBJECT_ID     = :P73_SUBJECT_ID',
'      AND NVL(SC.BOOK_ID,0) = NVL(:P73_BOOK_ID,0)',
'      AND SC.STUDENT_ID     = :P73_STUDENT_ID',
'      AND SC.SITE_ID        = :P73_SITE_ID',
'      ;',
'     EXCEPTION WHEN NO_DATA_FOUND THEN',
'       V_STATUS:=NULL;',
'    END',
'    ;    ',
'      IF V_CNT > 0 AND V_STATUS = :P73_STATUS THEN',
'         RETURN FALSE; ',
'      ELSE',
'         RETURN TRUE;',
'      END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'This lesson plan schedule already assign.'
,p_when_button_pressed=>wwv_flow_imp.id(33936195611242440925)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
