,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  V_CNT NUMBER;',
'  V_STATUS VARCHAR2(5);',
' BEGIN',
'   SELECT COUNT(*) INTO V_CNT',
'     FROM TEACHER_ASSIGN_TO_STUDENT T           ',
'    WHERE STUDENT_CLASS_SCHEDULE_ID = :P73_STUDENT_SCHEDULE_ID',
'      AND SITE_ID                   = :APP_SITE_ID',
'      ;',
'    IF V_CNT > 0 THEN  ',
'       SELECT STATUS INTO V_STATUS',
'         FROM TEACHER_ASSIGN_TO_STUDENT T           ',
'        WHERE STUDENT_CLASS_SCHEDULE_ID = :P73_STUDENT_SCHEDULE_ID',
'          AND SITE_ID                   = :APP_SITE_ID',
'          --AND STATUS                    = ''A''',
'          ;',
'         IF  V_STATUS = ''A'' THEN',
'            UPDATE TEACHER_ASSIGN_TO_STUDENT T               ',
'               SET STATUS = ''I''',
'             WHERE STUDENT_CLASS_SCHEDULE_ID = :P73_STUDENT_SCHEDULE_ID',
'               AND SITE_ID                   = :APP_SITE_ID',
'               AND STATUS                    = ''A''',
'          ;   ',
'         ELSIF V_STATUS = ''I'' THEN',
'               UPDATE TEACHER_ASSIGN_TO_STUDENT T               ',
'               SET STATUS = ''A''',
'             WHERE STUDENT_CLASS_SCHEDULE_ID = :P73_STUDENT_SCHEDULE_ID',
'               AND SITE_ID                   = :APP_SITE_ID',
'               AND STATUS                    = ''I''',
'          ;    ',
'        END IF;',
'      END IF;  ',
'END',
';      '))
,p_attribute_02=>'P73_STUDENT_SCHEDULE_ID'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
