wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(39982859836205300507)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(39948692222468733777)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Student Progress Test - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'V_SP_ID NUMBER;',
' BEGIN',
'      SELECT NVL(MAX(SP_ID),0) INTO V_SP_ID',
'       FROM STUDENT_PROGRESS S    ',
'      WHERE STUDENT_ID=:P79_STUDENT_ID',
'        AND SITE_ID   =:APP_SITE_ID',
'        ; ',
'    CASE :apex$row_status',
'       WHEN ''C'' THEN ',
'         INSERT INTO STUDENT_PROGRESS_TEST(SPT_DATE,SP_ID,TEST_NAME,TEST_DATE,PERCENTAGE,SITE_ID,FEED_BY,FEED_DATE)',
'             VALUES(TRUNC(SYSDATE),V_SP_ID,:TEST_NAME,:TEST_DATE,:PERCENTAGE,:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE))',
'             ;',
'        WHEN ''U'' THEN',
'            UPDATE STUDENT_PROGRESS_TEST',
'            SET TEST_NAME = :TEST_NAME,',
'                TEST_DATE = :TEST_DATE,',
'                PERCENTAGE=:PERCENTAGE',
'            WHERE SPT_ID   = :SPT_ID  ',
'              AND SITE_ID  = :APP_SITE_ID  ',
'            ;',
'              WHEN ''D'' THEN',
'            DELETE FROM  STUDENT_PROGRESS_TEST',
'                   WHERE SPT_ID   = :SPT_ID  ',
'                     AND SITE_ID  = :APP_SITE_ID  ',
'            ;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>39982859836205300507
);
