wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(39982860851122300517)
,p_plug_name=>'Progress Report'
,p_region_name=>'progress_report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html   CLOB := '''';',
'    v_title  VARCHAR2(100);',
'    v_test   NUMBER;',
'BEGIN',
'    FOR r IN (',
'        SELECT p.*, s.STUDENT_NAME, sb.SUBJECT_NAME, b.BOOK_NAME, e.EMP_NAME',
'        FROM STUDENT_PROGRESS p',
'        LEFT JOIN STUDENTS s ON s.STUDENT_ID = p.STUDENT_ID AND s.SITE_ID = p.SITE_ID',
'        LEFT JOIN SUBJECTS sb ON sb.SUBJECT_ID = p.SUBJECT_ID',
'        LEFT JOIN BOOKS b ON b.BOOK_ID = p.BOOK_ID',
'        LEFT JOIN EMPLOYEES e ON e.EMP_ID = p.EMP_ID',
'        WHERE p.STUDENT_ID = :P85_STUDENT_ID',
'          AND p.SP_ID = :P85_SP_ID',
'          AND p.SITE_ID = :APP_SITE_ID',
'        ORDER BY p.SP_DATE DESC',
'    ) LOOP',
'        -- Determine report title',
'        v_title := CASE r.PROGRESS_TYPE',
'                       WHEN ''M'' THEN ''Monthly Progress Report''',
'                       ELSE ''Progress Report''',
'                   END;',
'',
'        v_html := v_html ||',
'        ''<div class="progress-report" id="monthly_progress">'' ||',
unistr('        -- Replace \2193 this'),
'        -- ''<h2 class="center">Fine Tutors</h2>'' ||',
unistr('        -- With \2193 this'),
'        ''<div style="position: relative; text-align: center; margin-bottom: 10px;">'' ||',
'        ''  <h2 style="margin: 0;">Fine Tutors</h2>'' ||',
'        --'' <img src="#APP_FILES#fine_tutor-removebg-preview.png" alt="Logo" style="float: right; height: 50px; margin-left: 20px; margin-top: -50px; margin-bottom: 10px">'' ||',
'        ''</div>'' ||',
'        ''<h3 class="center">'' || v_title || ''</h3>'' ||',
'',
'        ''<!-- Student Information Table -->'' ||',
'       ''<table class="info-table" border="1" cellspacing="0" cellpadding="5">'' ||',
'        ''  <tr><th id="header" colspan="6" style="background-color:#ccc;">Student Information</th></tr>'' ||',
'        ''  <tr>'' ||',
'        ''    <td><strong>Date:</strong></td><td>'' || TO_CHAR(r.SP_DATE, ''DD-Mon-YYYY'') || ''</td>'' ||',
'        ''    <td><strong>Teacher:</strong></td><td>'' || NVL(r.EMP_NAME, ''-'') || ''</td>'' ||',
'        ''    <td><strong>Subject:</strong></td><td>'' || NVL(r.SUBJECT_NAME, ''-'') || ''</td>'' ||',
'        ''  </tr>'' ||',
'        ''  <tr>'' ||',
'        ''    <td><strong>Admission No:</strong></td><td>'' || r.STUDENT_ID || ''</td>'' ||',
'        ''    <td><strong>Student:</strong></td><td>'' || NVL(r.STUDENT_NAME, ''-'') || ''</td>'' ||',
'        ''    <td><strong>Book:</strong></td><td>'' || NVL(r.BOOK_NAME, ''-'') || ''</td>'' ||',
'        ''  </tr>'' ||',
'        ''</table>'' ||',
'',
'        ''<!-- Rating Guide -->'' ||',
'        ''<div class="rating-guide">'' ||',
'        ''  <span>1 = Cause for Concern</span>'' ||',
'        ''  <span>2 = Need for Improvement</span>'' ||',
'        ''  <span>3 = Fair</span>'' ||',
'        ''  <span>4 = Good</span>'' ||',
'        ''  <span>5 = Excellent</span>'' ||',
'        ''</div>'' ||',
'',
'        ''<!-- Rating Table -->'' ||',
'        ''<table class="rating-table" border="1" cellspacing="0" cellpadding="5" style="margin-top:20px;">'' ||',
'        ''  <tr><th id="header" colspan="2" style="background-color:#ccc;">Rating</th></tr>'' ||',
'        ''  <tr><td>Class Work</td><td>'' || r.CLASS_WORK || ''</td></tr>'' ||',
'        ''  <tr><td>Home Work</td><td>'' || r.HOME_WORK || ''</td></tr>'' ||',
'        ''  <tr><td>Attitude</td><td>'' || r.ATTITUDE || ''</td></tr>'' ||',
'        ''  <tr><td>Attendance</td><td>'' || r.ATTENDANCE || ''</td></tr>'' ||',
'        ''</table>'';',
'',
'        -- Count test records',
'        SELECT COUNT(*)',
'        INTO v_test',
'        FROM STUDENT_PROGRESS_TEST',
'        WHERE SP_ID = r.SP_ID AND SITE_ID = r.SITE_ID;',
'',
'        -- Only show table if test data exists',
'        IF v_test > 0 THEN',
'            v_html := v_html ||',
'            ''<!-- Test Records Table -->'' ||',
'            ''<h4>Test Records</h4>'' ||',
'            ''<table class="test-table" border="1" cellspacing="0" cellpadding="5" style="margin-top:20px;">'' ||',
'            ''  <tr id="test_id"><th>Test Name</th><th>Date</th><th>Percentage</th></tr>'';',
'',
'            FOR t IN (',
'                SELECT *',
'                FROM STUDENT_PROGRESS_TEST',
'                WHERE SP_ID = r.SP_ID AND SITE_ID = r.SITE_ID',
'                ORDER BY TEST_DATE',
'            ) LOOP',
'                v_html := v_html ||',
'                ''  <tr>'' ||',
'                ''    <td>'' || NVL(t.TEST_NAME, ''-'') || ''</td>'' ||',
'                ''    <td>'' || NVL(TO_CHAR(t.TEST_DATE, ''DD-Mon-YYYY''), ''-'') || ''</td>'' ||',
'                ''    <td>'' || NVL(TO_CHAR(NVL(t.PERCENTAGE, 0)), ''-'') || ''%</td>'' ||',
'                ''  </tr>'';',
'            END LOOP;',
'',
'            v_html := v_html || ''</table>'';',
'        END IF;',
'',
'        -- Feedback Section',
'              -- Feedback Section and WhatsApp icon',
'        v_html := v_html ||',
'        ''</table>'' ||',
'        ''<div class="feedback-section" style="border: none; border-collapse: collapse; margin-top:20px;">'' ||',
'        ''  <table class="feedback-table" width="100%">'' ||',
'        ''    <tr><th id="header" colspan="2" style="font-weight:bold; background-color:#ccc;">Teacher''''s Feedback</th></tr>'' ||',
'        ''    <tr><th id="feedback_section" colspan="2" style="text-align:left; font-weight:bold;">Current Progress (Specific topics student has improved in):</th></tr>'' ||',
'        ''    <tr><td colspan="2">'' || NVL(r.CURRENT_PROGRESS, ''-'') || ''</td></tr>'' ||',
'        ''    <tr><th id="feedback_section" colspan="2" style="text-align:left; font-weight:bold;">Targets (Specific topics student needs to improve in and the action that will be taken by teacher):</th></tr>'' ||',
'        ''    <tr><td colspan="2">'' || NVL(r.TARGET, ''-'') || ''</td></tr>'' ||',
'        ''    <tr><th id="feedback_section" colspan="2" style="text-align:left; font-weight:bold;">GENERAL COMMENTS</th></tr>'' ||',
'        ''    <tr><td colspan="2">'' || NVL(r.GENERAL_COMMENTS, ''-'') || ''</td></tr>'' ||',
'        ''  </table>'' ||',
'        ''  <div id="whatsapp_link" style="text-align: right; margin-top: 10px;">'' ||',
'        ''    <a href="https://web.whatsapp.com" target="_blank" title="Chat on WhatsApp">'' ||',
'        ''      <img src="https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg" alt="WhatsApp" width="70" height="70" style="cursor:pointer;">'' ||',
'        ''    </a>'' ||',
'        ''  </div>'' ||',
'        ''</div>'' ||',
'        ''<hr style="margin:40px 0;"/>'';',
'',
'    END LOOP;',
'',
'    -- Output HTML',
'  RETURN v_html;',
'    HTP.P(v_html);',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P85_STUDENT_ID'
);
