wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(93202288757536816289)
,p_name=>'Student Monthly Fee'
,p_template=>4072358936313175081
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT  DENSE_RANK() OVER (',
'         ORDER BY STUDENT_ID,SORTED_FEE_MONTH',
'       ) SERIAL_NO,FEE_MONTH,STUDENT_ID,STUDENT_NAME,STUDENT_TYPE,CLASS_ID,CLASS_NAME,SITE_ID,SITE_NAME,(SELECT TO_CHAR(MAX(F.DUE_DATE),''DD'') FROM STUDENT_FEES F WHERE F.STUDENT_ID = STUDENT_ID AND F.STATUS = ''A'')DUE_DATE,OPENING_BALANCE,TOTAL_MONTHL'
||'Y_FEE,ADMISSION_FEE,TOTAL_DISCOUNT,TOTAL_EXAM_FEE,TOTAL_BOOK_FEE,TOTAL_PAST_PAPER_FEE,',
'       TOTAL_FEE+OPENING_BALANCE AS TOTAL_FEE,--CASE WHEN ABS(OPENING_BALANCE) > TOTAL_FEE THEN TOTAL_FEE ELSE TOTAL_FEE+OPENING_BALANCE END AS TOTAL_FEE,',
'       TOTAL_RECEIVED_AMOUNT,CLOSING_BALANCE,SORTED_FEE_MONTH,SUSPENDED,COMMENTS_IF_ANY,PAYMENT_COUNT1,PAYMENT_COUNT2,PAYMENT_COUNT3,PAYMENT_DATE1,PAYMENT_DATE2,PAYMENT_DATE3,',
'       CASE WHEN PAYMENT_NAME1=''Adjustment'' THEN NULL ELSE PAYMENT_NAME1 END AS PAYMENT_NAME1,CASE WHEN PAYMENT_NAME2=''Adjustment'' THEN NULL ELSE PAYMENT_NAME2 END AS PAYMENT_NAME2,',
'       CASE WHEN PAYMENT_NAME3=''Adjustment'' THEN NULL ELSE PAYMENT_NAME3 END AS PAYMENT_NAME3,COMMENTS,REMINDER_DATE1,REMINDER_DATE2,REMINDER_DATE3,REMINDER_COMMENTS,STATUS,',
'       ''Detail'' Detail',
'   FROM(      ',
'        SELECT TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') FEE_MONTH,B.STUDENT_ID,STUDENT_NAME,STUDENT_TYPE,CLASS_ID,CLASS_NAME,B.SITE_ID,SITE_NAME,',
'                CASE WHEN (:P88_FEE_MONTH IS NULL OR (:P88_FEE_MONTH <> TO_CHAR(SYSDATE,''MON-YYYY''))) AND LAG(CLOSING_BALANCE,1) OVER (PARTITION BY B.STUDENT_ID, SITE_NAME ORDER BY TO_DATE(FEE_MONTH, ''MM-YYYY'')) IS NULL THEN',
'                           NVL(OPENING_BALANCE1,0)',
'                    WHEN (:P88_FEE_MONTH IS NULL OR (:P88_FEE_MONTH <> TO_CHAR(SYSDATE,''MON-YYYY''))) AND LAG(CLOSING_BALANCE,1,0) OVER (PARTITION BY B.STUDENT_ID, SITE_NAME ORDER BY TO_DATE(FEE_MONTH, ''MM-YYYY'')) IS NOT NULL THEN',
'                         LAG(CLOSING_BALANCE,1,0) OVER  (PARTITION BY B.STUDENT_ID, SITE_NAME ORDER BY TO_DATE(FEE_MONTH, ''MM-YYYY''))',
'                    WHEN :P88_FEE_MONTH = TO_CHAR(SYSDATE,''MON-YYYY'') THEN OPENING_BALANCE1 END AS OPENING_BALANCE,',
'               TOTAL_MONTHLY_FEE,ADMISSION_FEE,TOTAL_DISCOUNT,TOTAL_EXAM_FEE,TOTAL_BOOK_FEE,TOTAL_PAST_PAPER_FEE,TOTAL_FEE,                   ',
'               TOTAL_RECEIVED_AMOUNT,CLOSING_BALANCE,SORTED_FEE_MONTH,SUSPENDED,COMMENTS_IF_ANY,PAYMENT_COUNT1,PAYMENT_COUNT2,PAYMENT_COUNT3,PAYMENT_DATE1,PAYMENT_DATE2,PAYMENT_DATE3,PAYMENT_NAME1,PAYMENT_NAME2,PAYMENT_NAME3,',
'               COMMENTS1||''  ''||COMMENTS2||''  ''||COMMENTS3 COMMENTS,REMINDER_DATE1,REMINDER_DATE2,REMINDER_DATE3,',
'               REMINDER_COMMENT1||'' ''||REMINDER_COMMENT2||''  ''||REMINDER_COMMENT3 REMINDER_COMMENTS,STATUS',
'          FROM(',
'        SELECT FEE_MONTH,STUDENT_ID,STUDENT_NAME,STUDENT_TYPE,CLASS_ID,CLASS_NAME,SITE_ID,SITE_NAME,TOTAL_MONTHLY_FEE,ADMISSION_FEE,TOTAL_DISCOUNT,TOTAL_EXAM_FEE,TOTAL_BOOK_FEE,TOTAL_PAST_PAPER_FEE,TOTAL_FEE,TOTAL_RECEIVED_AMOUNT,',
'               SORTED_FEE_MONTH,SUSPENDED,COMMENTS_IF_ANY,PAYMENT_COUNT1,PAYMENT_COUNT2,PAYMENT_COUNT3,PAYMENT_DATE1,PAYMENT_DATE2,PAYMENT_DATE3,PAYMENT_NAME1,PAYMENT_NAME2,PAYMENT_NAME3,COMMENTS1,COMMENTS2,COMMENTS3,REMINDER_DATE1,REMINDER_DATE2,REM'
||'INDER_DATE3',
'               ,REMINDER_COMMENT1,REMINDER_COMMENT2,REMINDER_COMMENT3,STATUS,',
'              (SELECT NVL(SOB.CLOSING_BALANCE, 0)',
'                 FROM STUDENT_FEE_COLLECTION SOB ',
'                 WHERE SOB.STUDENT_ID = A.STUDENT_ID ',
'                   AND SOB.SITE_ID = A.SITE_ID ',
'                   AND SOB.FEE_MONTH = A.FEE_MONTH',
'                   AND FEE_COLLECTION_ID = ',
'                     (SELECT MAX(SFI.FEE_COLLECTION_ID) ',
'                      FROM STUDENT_FEE_COLLECTION SFI ',
'                      WHERE SFI.STUDENT_ID = A.STUDENT_ID ',
'                        AND SFI.SITE_ID = A.SITE_ID ',
'                        AND SFI.FEE_MONTH = A.FEE_MONTH)',
'                ) AS CLOSING_BALANCE,',
'                 (SELECT NVL(SOB.OPENING_BALANCE, 0)',
'                 FROM STUDENT_FEE_COLLECTION SOB ',
'                 WHERE SOB.STUDENT_ID = A.STUDENT_ID ',
'                   AND SOB.SITE_ID = A.SITE_ID ',
'                   AND SOB.FEE_MONTH = A.FEE_MONTH',
'                   AND FEE_COLLECTION_ID = ',
'                     (SELECT MIN(SFI.FEE_COLLECTION_ID) ',
'                      FROM STUDENT_FEE_COLLECTION SFI ',
'                      WHERE SFI.STUDENT_ID = A.STUDENT_ID ',
'                        AND SFI.SITE_ID = A.SITE_ID ',
'                        AND SFI.FEE_MONTH = A.FEE_MONTH)',
'                ) AS OPENING_BALANCE1',
'',
'          FROM(   ',
'            SELECT SFC.FEE_MONTH,S.STAGE||''-''||SFC.STUDENT_ID STUDENT_ID,S.STUDENT_NAME || '' '' || S.LAST_NAME AS STUDENT_NAME,S.STUDENT_TYPE,S.CLASS_ID,C.CLASS_NAME,SFC.SITE_ID,ST.SITE_NAME,NVL(SFC.MONTHLY_FEE,0) AS TOTAL_MONTHLY_FEE, NVL(SUM(REGISTR'
||'ATION_FEE),0)ADMISSION_FEE, NVL(SUM(SFC.DISCOUNT),0) AS TOTAL_DISCOUNT,  ',
'                NVL(SUM(SFC.EXAM_FEE),0) AS TOTAL_EXAM_FEE,  NVL(SUM(SFC.BOOKS_FEE),0) AS TOTAL_BOOK_FEE,  NVL(SUM(SFC.PAST_PAPER_FEE),0) AS TOTAL_PAST_PAPER_FEE,  ((NVL(SFC.MONTHLY_FEE,0)) +NVL(SUM(REGISTRATION_FEE),0)+ NVL(SUM(SFC.DISCOUNT),0) + NV'
||'L(SUM(SFC.EXAM_FEE),0) + NVL(SUM(SFC.PAST_PAPER_FEE),0)+NVL(SUM(SFC.BOOKS_FEE),0) ) AS TOTAL_FEE,  ',
'                NVL(SUM(SFC.RECEIVED_AMOUNT),0) AS TOTAL_RECEIVED_AMOUNT,DECODE(S.STATUS,''A'',''Active'',''I'',''In-Active'')STATUS,',
'                MAX(CASE WHEN PAYMENT_COUNT = 1 THEN ''Payment '' || PAYMENT_COUNT ELSE NULL END) AS PAYMENT_COUNT1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN ''Payment '' || PAYMENT_COUNT ELSE NULL END) AS PAYMENT_COUNT2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN ''Payment '' || PAYMENT_COUNT ELSE NULL END) AS PAYMENT_COUNT3,',
'                -- Payment Dates',
'                MAX(CASE WHEN PAYMENT_COUNT = 1 THEN TO_CHAR(SFC.PAYMENT_DATE, ''DD-MON-YYYY'') ELSE NULL END) AS PAYMENT_DATE1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN TO_CHAR(SFC.PAYMENT_DATE, ''DD-MON-YYYY'') ELSE NULL END) AS PAYMENT_DATE2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN TO_CHAR(SFC.PAYMENT_DATE, ''DD-MON-YYYY'') ELSE NULL END) AS PAYMENT_DATE3,',
'                -- Payment Names',
'                MAX(CASE WHEN PAYMENT_COUNT = 1 THEN ',
'                     (SELECT P.PAYMENT_NAME FROM PAYMENT_TYPE P WHERE P.PAY_ID = SFC.PAYMENT_METHOD) ELSE NULL END) AS PAYMENT_NAME1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN ',
'                     (SELECT P.PAYMENT_NAME FROM PAYMENT_TYPE P WHERE P.PAY_ID = SFC.PAYMENT_METHOD) ELSE NULL END) AS PAYMENT_NAME2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN ',
'                     (SELECT P.PAYMENT_NAME FROM PAYMENT_TYPE P WHERE P.PAY_ID = SFC.PAYMENT_METHOD) ELSE NULL END) AS PAYMENT_NAME3,     ',
'                 --COMMENTS',
'                MAX(CASE WHEN PAYMENT_COUNT = 1 THEN SFC.COMMENTS ELSE NULL END) AS COMMENTS1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN SFC.COMMENTS ELSE NULL END) AS COMMENTS2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN SFC.COMMENTS ELSE NULL END) AS COMMENTS3,',
'                TO_DATE(SFC.FEE_MONTH, ''MM-YYYY'') AS SORTED_FEE_MONTH,',
'                (SELECT MAX(F1.REMINDER_DATE)',
'                 FROM FEE_REMINDER F1',
'                 WHERE F1.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F1.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F1.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   AND F1.REMINDER_COUNT = 1) AS REMINDER_DATE1,',
'',
'                (SELECT MAX(F2.REMINDER_DATE)',
'                 FROM FEE_REMINDER F2',
'                 WHERE F2.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F2.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F2.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   AND F2.REMINDER_COUNT = 2) AS REMINDER_DATE2,',
'',
'                 (SELECT MAX(F5.REMINDER_DATE)',
'                 FROM FEE_REMINDER F5',
'                 WHERE F5.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F5.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F5.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   AND F5.REMINDER_COUNT = 3) AS REMINDER_DATE3,   ',
'',
'                (SELECT MAX(F3.REMINDER_COMMENT)',
'                 FROM FEE_REMINDER F3',
'                 WHERE F3.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F3.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F3.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   AND F3.REMINDER_COUNT = 1) AS REMINDER_COMMENT1,',
'',
'                (SELECT MAX(F4.REMINDER_COMMENT)',
'                 FROM FEE_REMINDER F4',
'                 WHERE F4.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F4.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F4.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   AND F4.REMINDER_COUNT = 2) AS REMINDER_COMMENT2,',
'',
'                (SELECT MAX(F6.REMINDER_COMMENT)',
'                 FROM FEE_REMINDER F6',
'                 WHERE F6.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F6.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F6.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   AND F6.REMINDER_COUNT = 3) AS REMINDER_COMMENT3, ',
'',
'                 (SELECT MAX(F7.SUSPENDED)',
'                 FROM FEE_REMINDER F7',
'                 WHERE F7.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F7.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F7.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   ) AS SUSPENDED,    ',
'',
'                (SELECT MAX(F8.COMMENTS_IF_ANY)',
'                 FROM FEE_REMINDER F8',
'                 WHERE F8.STUDENT_ID = SFC.STUDENT_ID',
'                   AND F8.SITE_ID = SFC.SITE_ID',
'                   AND TO_CHAR(F8.REMINDER_DATE, ''MM-YYYY'') = SFC.FEE_MONTH',
'                   ) AS COMMENTS_IF_ANY  ',
'',
'            FROM STUDENT_FEE_COLLECTION SFC, STUDENTS S, CLASSES C, SITES ST',
'            WHERE SFC.STUDENT_ID = S.STUDENT_ID',
'              AND SFC.SITE_ID = S.SITE_ID',
'              AND S.CLASS_ID = C.CLASS_ID',
'              AND SFC.SITE_ID = ST.SITE_ID',
'              /*AND F.STUDENT_ID(+)=SFC.STUDENT_ID',
'              AND F.SITE_ID(+)   =SFC.SITE_ID',
'              AND TO_CHAR(F.REMINDER_DATE(+),''MM-YYYY'')=TO_CHAR(TO_DATE(SFC.FEE_MONTH, ''MM-YYYY''), ''MM-YYYY'')*/',
'              --AND SFC.STUDENT_ID = ''K301''',
'             AND SFC.SITE_ID = :P88_BRANCHES',
'            GROUP BY SFC.FEE_MONTH, S.STAGE, SFC.STUDENT_ID, S.STUDENT_NAME, S.LAST_NAME,S.STUDENT_TYPE,S.STATUS,S.CLASS_ID,C.CLASS_NAME,SFC.SITE_ID, ST.SITE_NAME, SFC.MONTHLY_FEE',
'            ORDER BY TO_DATE(SFC.FEE_MONTH, ''MM-YYYY'') ASC',
'          )A',
'        )B',
'   )',
'WHERE STUDENT_ID=NVL(:P88_STUDENT_ID,STUDENT_ID)',
'  AND TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') =NVL(TO_CHAR(TO_DATE(:P88_FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') ,TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY''))',
'  AND ((:P88_FEE_STATUS=''P'' AND (CLOSING_BALANCE > 0)) OR (:P88_FEE_STATUS=''A'' AND (CLOSING_BALANCE < 0)) OR :P88_FEE_STATUS IS NULL)    ',
'ORDER BY STUDENT_ID,SORTED_FEE_MONTH ASC,DENSE_RANK() OVER (',
'                                 ORDER BY STUDENT_ID,SORTED_FEE_MONTH',
'                               )'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P88_STUDENT_ID,P88_FEE_MONTH,P88_FEE_STATUS,P88_BRANCHES'
,p_lazy_loading=>true
