wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(103620536669067992565)
,p_plug_name=>'Student Current Month Fee'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT FEE_MONTH,STUDENT_ID,STUDENT_NAME,STUDENT_TYPE,STATUS,SITE_ID,CLASS_NAME,TO_CHAR(DUE_DATE,''DD'')DUE_DATE,',
'    CASE WHEN NVL(PRV_MONTHLY_FEE,0)=NVL(OPENING_BALANCE,0) AND FEE_MONTH IS NOT NULL THEN NVL(OPENING_BALANCE,0) ',
'     WHEN NVL(PRV_MONTHLY_FEE,0)<>NVL(OPENING_BALANCE,0) AND FEE_MONTH IS NOT NULL AND NVL(PRV_MONTHLY_FEE,0) <> 0  THEN NVL(PRV_MONTHLY_FEE,0)',
'     WHEN NVL(PRV_MONTHLY_FEE,0)<>NVL(OPENING_BALANCE,0) AND FEE_MONTH IS NOT NULL AND NVL(PRV_MONTHLY_FEE,0) = 0  THEN NVL(OPENING_BALANCE,0)',
'     ELSE (NVL(PRV_MONTHLY_FEE,0)+NVL(OPENING_BALANCE,0)) END AS OPENING_BALANCE,',
'       TOTAL_MONTHLY_FEE,TOTAL_DISCOUNT,ADMISSION_FEE,TOTAL_EXAM_FEE,TOTAL_BOOK_FEE,TOTAL_PAST_PAPER_FEE,PRV_MONTHLY_FEE,',
'       TOTAL_FEE,TOTAL_RECEIVED_AMOUNT,CLOSING_BALANCE,PAYMENT_COUNT1,PAYMENT_COUNT2,PAYMENT_COUNT3,PAYMENT_DATE1,PAYMENT_DATE2,PAYMENT_DATE3,',
'       CASE WHEN PAYMENT_NAME1=''Adjustment'' THEN NULL ELSE PAYMENT_NAME1 END AS PAYMENT_NAME1,CASE WHEN PAYMENT_NAME2=''Adjustment'' THEN NULL ELSE PAYMENT_NAME2 END AS PAYMENT_NAME2,',
'       CASE WHEN PAYMENT_NAME3=''Adjustment'' THEN NULL ELSE PAYMENT_NAME3 END AS PAYMENT_NAME3,COMMENTS,REMINDER_DATE1,REMINDER_DATE2,REMINDER_DATE3,REMINDER_COMMENTS,SUSPENDED,COMMENTS_IF_ANY',
'  FROM(    ',
'        SELECT FEE_MONTH,STUDENT_ID,STUDENT_NAME,STUDENT_TYPE,STATUS,SITE_ID,CLASS_NAME,DUE_DATE,CASE WHEN OPENING_BALANCE IS NULL THEN OP_BALANCE ELSE OPENING_BALANCE END AS OPENING_BALANCE,TOTAL_MONTHLY_FEE,TOTAL_DISCOUNT,',
'        ADMISSION_FEE,TOTAL_EXAM_FEE,TOTAL_BOOK_FEE,TOTAL_PAST_PAPER_FEE,PRV_MONTHLY_FEE,',
'        CASE WHEN NVL(TOTAL_FEE,0) > 0 THEN (TOTAL_FEE+NVL(PRV_MONTHLY_FEE,0)) ELSE (OPENING_BALANCE+TOTAL_MONTHLY_FEE+TOTAL_DISCOUNT+ADMISSION_FEE+TOTAL_EXAM_FEE+TOTAL_BOOK_FEE+TOTAL_PAST_PAPER_FEE+NVL(PRV_MONTHLY_FEE,0)) END AS TOTAL_FEE,TOTAL_RECE'
||'IVED_AMOUNT,',
'        CASE WHEN CLOSING_BALANCE IS NOT NULL THEN CLOSING_BALANCE ELSE OPENING_BALANCE+TOTAL_MONTHLY_FEE+TOTAL_DISCOUNT+ADMISSION_FEE+TOTAL_EXAM_FEE+TOTAL_BOOK_FEE+TOTAL_PAST_PAPER_FEE+NVL(PRV_MONTHLY_FEE,0) END AS CLOSING_BALANCE',
'         ,PAYMENT_COUNT1,PAYMENT_COUNT2,PAYMENT_COUNT3,PAYMENT_DATE1,PAYMENT_DATE2,PAYMENT_DATE3,PAYMENT_NAME1,PAYMENT_NAME2,',
'         PAYMENT_NAME3,COMMENTS,REMINDER_DATE1,REMINDER_DATE2,REMINDER_DATE3,REMINDER_COMMENTS,SUSPENDED,COMMENTS_IF_ANY',
'          FROM(',
'        SELECT',
'          TO_CHAR(TO_DATE(FEE_MONTH, ''MM-YYYY''), ''MON-YYYY'') AS FEE_MONTH,STAGE||''-''||B.STUDENT_ID STUDENT_ID,STUDENT_NAME,STUDENT_TYPE,F.STATUS,B.SITE_ID,CLASS_NAME,DUE_DATE,NVL(OPENING_BALANCE,0) OPENING_BALANCE,',
'           CASE WHEN NVL(TOTAL_MONTHLY_FEE,0) > 0 THEN TOTAL_MONTHLY_FEE ELSE NVL(F.TOTAL_FEE,0) END AS TOTAL_MONTHLY_FEE',
'          ,TOTAL_DISCOUNT,CASE WHEN NVL(ADMISSION_FEE,0) > 0 OR NVL(ADD_FEE_COLLECTION,0) > 0 THEN ADMISSION_FEE ELSE NVL(F.REGISTRATION_FEE,0) END AS ADMISSION_FEE,',
'          CASE WHEN NVL(TOTAL_EXAM_FEE,0) > 0 OR NVL(EXAM_FEE_COLLECTION,0) > 0 THEN TOTAL_EXAM_FEE ELSE NVL(F.EXAM_FEE,0) END AS TOTAL_EXAM_FEE,',
'          CASE WHEN NVL(TOTAL_BOOK_FEE,0) > 0 OR NVL(BOOKS_FEE_COLLECTION,0) > 0 THEN TOTAL_BOOK_FEE ELSE NVL(F.BOOK_FEE,0) END AS TOTAL_BOOK_FEE,',
'          CASE WHEN NVL(TOTAL_PAST_PAPER_FEE,0) > 0 OR NVL(PAST_PAPER_FEE_COLLECTION,0) > 0 THEN TOTAL_PAST_PAPER_FEE ELSE NVL(F.PAST_PAPER_FEE,0) END AS TOTAL_PAST_PAPER_FEE,',
'          /*CASE',
'            WHEN ABS(NVL(OPENING_BALANCE,0)) > B.TOTAL_FEE',
'            THEN B.TOTAL_FEE',
'            ELSE ((B.TOTAL_FEE + ABS(NVL(OPENING_BALANCE,0))))',
'          END AS TOTAL_FEE,*/B.TOTAL_FEE,',
'          PRV_MONTHLY_FEE,OP_BALANCE, TOTAL_RECEIVED_AMOUNT,CLOSING_BALANCE,',
'          PAYMENT_COUNT1,PAYMENT_COUNT2,PAYMENT_COUNT3,PAYMENT_DATE1,PAYMENT_DATE2,PAYMENT_DATE3,PAYMENT_NAME1,PAYMENT_NAME2,PAYMENT_NAME3,',
'          COMMENTS1||''  ''||COMMENTS2||''  ''||COMMENTS3 COMMENTS,REMINDER_DATE1,REMINDER_DATE2,REMINDER_DATE3,',
'          REMINDER_COMMENT1||'' ''||REMINDER_COMMENT2||''  ''||REMINDER_COMMENT3 REMINDER_COMMENTS,SUSPENDED,COMMENTS_IF_ANY',
'        FROM (',
'          SELECT',
'            FEE_MONTH,STAGE,STUDENT_ID,STUDENT_NAME,STUDENT_TYPE,STATUS,SITE_ID,CLASS_NAME,TOTAL_MONTHLY_FEE,ADMISSION_FEE,TOTAL_DISCOUNT,TOTAL_EXAM_FEE,TOTAL_BOOK_FEE,TOTAL_PAST_PAPER_FEE,TOTAL_FEE,TOTAL_RECEIVED_AMOUNT,',
'            PAYMENT_COUNT1,PAYMENT_COUNT2,PAYMENT_COUNT3,PAYMENT_DATE1,PAYMENT_DATE2,PAYMENT_DATE3,PAYMENT_NAME1,PAYMENT_NAME2,PAYMENT_NAME3,COMMENTS1,COMMENTS2,COMMENTS3,',
'            (',
'              SELECT NVL(SOB.CLOSING_BALANCE, 0)',
'              FROM STUDENT_FEE_COLLECTION SOB',
'              WHERE SOB.STUDENT_ID = A.STUDENT_ID',
'                AND SOB.SITE_ID = A.SITE_ID',
'                AND SOB.FEE_MONTH < A.FEE_MONTH',
'                AND FEE_COLLECTION_ID = (',
'                  SELECT MAX(SFI.FEE_COLLECTION_ID)',
'                  FROM STUDENT_FEE_COLLECTION SFI',
'                  WHERE SFI.STUDENT_ID = A.STUDENT_ID',
'                    AND SFI.SITE_ID = A.SITE_ID',
'                    AND SFI.FEE_MONTH < A.FEE_MONTH',
'                )',
'            ) AS OPENING_BALANCE,',
'            (',
'              SELECT NVL(SOB.CLOSING_BALANCE, 0)',
'              FROM STUDENT_FEE_COLLECTION SOB',
'              WHERE SOB.STUDENT_ID = A.STUDENT_ID',
'                AND SOB.SITE_ID = A.SITE_ID',
'                AND SOB.FEE_MONTH = A.FEE_MONTH',
'                AND FEE_COLLECTION_ID = (',
'                  SELECT MAX(SFI.FEE_COLLECTION_ID)',
'                  FROM STUDENT_FEE_COLLECTION SFI',
'                  WHERE SFI.STUDENT_ID = A.STUDENT_ID',
'                    AND SFI.SITE_ID = A.SITE_ID',
'                    AND SFI.FEE_MONTH = A.FEE_MONTH',
'                )',
'',
'            ) AS CLOSING_BALANCE,',
'              (',
'              SELECT NVL(SOB.OPENING_BALANCE, 0)',
'              FROM STUDENT_FEE_COLLECTION SOB',
'              WHERE SOB.STUDENT_ID = A.STUDENT_ID',
'                AND SOB.SITE_ID = A.SITE_ID',
'                AND SOB.FEE_MONTH = A.FEE_MONTH',
'                AND FEE_COLLECTION_ID = (',
'                                          SELECT MIN(SFI.FEE_COLLECTION_ID)',
'                                          FROM STUDENT_FEE_COLLECTION SFI',
'                                          WHERE SFI.STUDENT_ID = A.STUDENT_ID',
'                                            AND SFI.SITE_ID = A.SITE_ID',
'                                            AND SFI.FEE_MONTH = A.FEE_MONTH',
'                                        )',
'',
'            ) AS OP_BALANCE,----GET MANUAL OP BALANACE-- AGAR MENUAL OP BALANCE KHUD ADD KAREN TUB YE AEE',
'            A.PRV_MONTHLY_FEE,',
'        (',
'          SELECT COUNT(1)',
'          FROM STUDENT_FEE_COLLECTION SFC2',
'          WHERE SFC2.STUDENT_ID = A.STUDENT_ID',
'            AND SFC2.SITE_ID = A.SITE_ID',
'            AND SFC2.REGISTRATION_FEE IS NOT NULL',
'        ) AS ADD_FEE_COLLECTION,',
'            (',
'          SELECT COUNT(1)',
'          FROM STUDENT_FEE_COLLECTION SFC2',
'          WHERE SFC2.STUDENT_ID = A.STUDENT_ID',
'            AND SFC2.SITE_ID = A.SITE_ID',
'            AND SFC2.EXAM_FEE IS NOT NULL',
'        ) AS EXAM_FEE_COLLECTION,',
'          (',
'          SELECT COUNT(1)',
'          FROM STUDENT_FEE_COLLECTION SFC2',
'          WHERE SFC2.STUDENT_ID = A.STUDENT_ID',
'            AND SFC2.SITE_ID = A.SITE_ID',
'            AND SFC2.PAST_PAPER_FEE IS NOT NULL',
'        ) AS PAST_PAPER_FEE_COLLECTION,',
'         (',
'          SELECT COUNT(1)',
'          FROM STUDENT_FEE_COLLECTION SFC2',
'          WHERE SFC2.STUDENT_ID = A.STUDENT_ID',
'            AND SFC2.SITE_ID = A.SITE_ID',
'            AND SFC2.BOOKS_FEE IS NOT NULL',
'        ) AS BOOKS_FEE_COLLECTION,',
'',
'          (SELECT MAX(F1.REMINDER_DATE)',
'                 FROM FEE_REMINDER F1',
'                 WHERE F1.STUDENT_ID = A.STUDENT_ID',
'                   AND F1.SITE_ID    = A.SITE_ID',
'                   AND TO_CHAR(F1.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   AND F1.REMINDER_COUNT = 1) AS REMINDER_DATE1,',
'',
'                (SELECT MAX(F2.REMINDER_DATE)',
'                 FROM FEE_REMINDER F2',
'                 WHERE F2.STUDENT_ID = A.STUDENT_ID',
'                   AND F2.SITE_ID = A.SITE_ID',
'                   AND TO_CHAR(F2.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   AND F2.REMINDER_COUNT = 2) AS REMINDER_DATE2,',
'',
'                 (SELECT MAX(F5.REMINDER_DATE)',
'                 FROM FEE_REMINDER F5',
'                 WHERE F5.STUDENT_ID = A.STUDENT_ID',
'                   AND F5.SITE_ID = A.SITE_ID',
'                   AND TO_CHAR(F5.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   AND F5.REMINDER_COUNT = 3) AS REMINDER_DATE3,  ',
'',
'                (SELECT MAX(F3.REMINDER_COMMENT)',
'                 FROM FEE_REMINDER F3',
'                 WHERE F3.STUDENT_ID = A.STUDENT_ID',
'                   AND F3.SITE_ID = A.SITE_ID',
'                   AND TO_CHAR(F3.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   AND F3.REMINDER_COUNT = 1) AS REMINDER_COMMENT1,',
'',
'                (SELECT MAX(F4.REMINDER_COMMENT)',
'                 FROM FEE_REMINDER F4',
'                 WHERE F4.STUDENT_ID = A.STUDENT_ID',
'                   AND F4.SITE_ID = A.SITE_ID',
'                   AND TO_CHAR(F4.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   AND F4.REMINDER_COUNT = 2) AS REMINDER_COMMENT2,',
'',
'                (SELECT MAX(F6.REMINDER_COMMENT)',
'                 FROM FEE_REMINDER F6',
'                 WHERE F6.STUDENT_ID = A.STUDENT_ID',
'                   AND F6.SITE_ID = A.SITE_ID',
'                   AND TO_CHAR(F6.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   AND F6.REMINDER_COUNT = 3) AS REMINDER_COMMENT3,',
'',
'                 (SELECT MAX(F7.SUSPENDED)',
'                 FROM FEE_REMINDER F7',
'                 WHERE F7.STUDENT_ID = A.STUDENT_ID',
'                   AND F7.SITE_ID = A.SITE_ID',
'                   AND TO_CHAR(F7.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   ) AS SUSPENDED,   ',
'',
'                (SELECT MAX(F8.COMMENTS_IF_ANY)',
'                 FROM FEE_REMINDER F8',
'                 WHERE F8.STUDENT_ID = A.STUDENT_ID',
'                   AND F8.SITE_ID = A.SITE_ID',
'                   AND TO_CHAR(F8.REMINDER_DATE, ''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'')',
'                   ) AS COMMENTS_IF_ANY ',
'          FROM (  ',
'            SELECT',
'              NVL(TO_CHAR(TO_DATE(SFC.FEE_MONTH, ''MM-YYYY''), ''MM-YYYY''), TO_CHAR(SYSDATE, ''MM-YYYY'')) AS FEE_MONTH, S.STAGE,S.STUDENT_ID,S.STUDENT_NAME || '' '' || S.LAST_NAME AS STUDENT_NAME,S.STUDENT_TYPE,DECODE(S.STATUS,''A'',''Active'',''I'',''In-Active'')'
||'STATUS,S.SITE_ID,C.CLASS_NAME,NVL(SFC.MONTHLY_FEE, 0) AS TOTAL_MONTHLY_FEE,',
'              NVL(SUM(SFC.REGISTRATION_FEE), 0) AS ADMISSION_FEE,NVL(SUM(SFC.DISCOUNT), 0) AS TOTAL_DISCOUNT,NVL(SUM(SFC.EXAM_FEE), 0) AS TOTAL_EXAM_FEE,NVL(SUM(SFC.BOOKS_FEE),0) AS TOTAL_BOOK_FEE,NVL(SUM(SFC.PAST_PAPER_FEE), 0) AS TOTAL_PAST_PAPER_F'
||'EE,',
'              (NVL(SFC.MONTHLY_FEE, 0) + NVL(SUM(SFC.REGISTRATION_FEE), 0) + NVL(SUM(SFC.DISCOUNT), 0) + NVL(SUM(SFC.EXAM_FEE), 0) + NVL(SUM(SFC.PAST_PAPER_FEE), 0)+NVL(SUM(SFC.BOOKS_FEE),0)) AS TOTAL_FEE,',
'              NVL(SUM(SFC.RECEIVED_AMOUNT), 0) AS TOTAL_RECEIVED_AMOUNT,',
'               MAX(CASE WHEN PAYMENT_COUNT = 1 THEN ''Payment '' || PAYMENT_COUNT ELSE NULL END) AS PAYMENT_COUNT1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN ''Payment '' || PAYMENT_COUNT ELSE NULL END) AS PAYMENT_COUNT2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN ''Payment '' || PAYMENT_COUNT ELSE NULL END) AS PAYMENT_COUNT3,',
'                -- Payment Dates',
'                MAX(CASE WHEN PAYMENT_COUNT = 1 THEN TO_CHAR(SFC.PAYMENT_DATE, ''DD-MON-YYYY'') ELSE NULL END) AS PAYMENT_DATE1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN TO_CHAR(SFC.PAYMENT_DATE, ''DD-MON-YYYY'') ELSE NULL END) AS PAYMENT_DATE2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN TO_CHAR(SFC.PAYMENT_DATE, ''DD-MON-YYYY'') ELSE NULL END) AS PAYMENT_DATE3,',
'                -- Payment Names',
'                MAX(CASE WHEN PAYMENT_COUNT = 1 THEN',
'                     (SELECT P.PAYMENT_NAME FROM PAYMENT_TYPE P WHERE P.PAY_ID = SFC.PAYMENT_METHOD) ELSE NULL END) AS PAYMENT_NAME1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN',
'                     (SELECT P.PAYMENT_NAME FROM PAYMENT_TYPE P WHERE P.PAY_ID = SFC.PAYMENT_METHOD) ELSE NULL END) AS PAYMENT_NAME2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN',
'                     (SELECT P.PAYMENT_NAME FROM PAYMENT_TYPE P WHERE P.PAY_ID = SFC.PAYMENT_METHOD) ELSE NULL END) AS PAYMENT_NAME3,    ',
'                 --COMMENTS',
'                MAX(CASE WHEN PAYMENT_COUNT = 1 THEN SFC.COMMENTS ELSE NULL END) AS COMMENTS1,',
'                MAX(CASE WHEN PAYMENT_COUNT = 2 THEN SFC.COMMENTS ELSE NULL END) AS COMMENTS2,',
'                MAX(CASE WHEN PAYMENT_COUNT = 3 THEN SFC.COMMENTS ELSE NULL END) AS COMMENTS3,',
'                TO_DATE(SFC.FEE_MONTH, ''MM-YYYY'') AS SORTED_FEE_MONTH,',
'              ( SELECT  ',
'                       CASE ',
'                            WHEN lf.MAX_FEE_MONTH IS NOT NULL ',
'                                 AND lf.MAX_FEE_MONTH = TO_CHAR(SYSDATE,''MM-YYYY'') THEN',
'                                NVL(ob.OPENING_BALANCE, 0)',
'                                ',
'                            WHEN lf.MAX_FEE_MONTH IS NULL ',
'                                 AND TO_CHAR(sf.FEE_START_DATE,''MM-YYYY'') = TO_CHAR(SYSDATE,''MM-YYYY'') THEN',
'                                GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, sf.FEE_START_DATE)), 0) * sf.TOTAL_FEE',
'                                ',
'                            WHEN lf.MAX_FEE_MONTH IS NULL ',
'                                 AND TO_CHAR(sf.FEE_START_DATE,''MM-YYYY'') <> TO_CHAR(SYSDATE,''MM-YYYY'') THEN',
'                                --GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, sf.FEE_START_DATE)+1), 0) * sf.TOTAL_FEE',
'                                 GREATEST(TRUNC(MONTHS_BETWEEN(TRUNC(SYSDATE,''MM''), sf.FEE_START_DATE)+1), 0) * sf.TOTAL_FEE',
'',
'                            WHEN st.INACTIVE_DATE IS NOT NULL AND st.ACTIVE_DATE IS NOT NULL',
'                                 AND st.ACTIVE_DATE > TO_DATE(lf.MAX_FEE_MONTH, ''MM-YYYY'') ',
'                                 AND TO_CHAR(st.ACTIVE_DATE,''MM-YYYY'') >= TO_CHAR(st.INACTIVE_DATE,''MM-YYYY'') THEN',
'                                --GREATEST(TRUNC(MONTHS_BETWEEN(st.ACTIVE_DATE, TO_DATE(lf.MAX_FEE_MONTH, ''MM-YYYY''))) - 1, 0) * sf.TOTAL_FEE',
'                                 GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, st.ACTIVE_DATE)), 0) * sf.TOTAL_FEE',
'                                ',
'                            WHEN ((st.INACTIVE_DATE IS NOT NULL AND st.ACTIVE_DATE IS NOT NULL) ',
'                                  OR (st.INACTIVE_DATE IS NULL AND st.ACTIVE_DATE IS NOT NULL))',
'                                 AND st.ACTIVE_DATE < TO_DATE(lf.MAX_FEE_MONTH, ''MM-YYYY'') ',
'                                 AND TO_DATE(lf.MAX_FEE_MONTH, ''MM-YYYY'') = TRUNC(SYSDATE) THEN',
'                                GREATEST(TRUNC(MONTHS_BETWEEN(TO_DATE(lf.MAX_FEE_MONTH, ''MM-YYYY''), st.ACTIVE_DATE) + 1),0) * sf.TOTAL_FEE',
'',
'                            /*WHEN st.INACTIVE_DATE IS NOT NULL AND st.ACTIVE_DATE IS NOT NULL AND TO_CHAR(st.INACTIVE_DATE,''MM-YYYY'') >= TO_CHAR(st.ACTIVE_DATE,''MM-YYYY'') THEN',
'                                               0    */',
'                            ELSE',
'                                GREATEST(TRUNC(MONTHS_BETWEEN(SYSDATE, TO_DATE(lf.MAX_FEE_MONTH, ''MM-YYYY''))) - 1, 0) * sf.TOTAL_FEE',
'                        END AS DUE_AMOUNT',
'',
'                    FROM STUDENTS st',
'                    JOIN STUDENT_FEES sf ',
'                        ON sf.STUDENT_ID = st.STUDENT_ID ',
'                       AND sf.SITE_ID = st.SITE_ID',
'                       AND SF.STATUS = ''A''',
'',
'                    LEFT JOIN (',
'                        SELECT STUDENT_ID, SITE_ID, MAX(FEE_MONTH) AS MAX_FEE_MONTH',
'                        FROM STUDENT_FEE_COLLECTION',
'                        GROUP BY STUDENT_ID, SITE_ID',
'                    ) lf',
'                        ON lf.STUDENT_ID = st.STUDENT_ID ',
'                       AND lf.SITE_ID = st.SITE_ID',
'',
'                    LEFT JOIN (',
'                        SELECT SOB.STUDENT_ID, SOB.SITE_ID, SOB.FEE_MONTH, SOB.OPENING_BALANCE',
'                        FROM STUDENT_FEE_COLLECTION SOB',
'                        WHERE (SOB.STUDENT_ID, SOB.SITE_ID, SOB.FEE_MONTH, SOB.FEE_COLLECTION_ID) IN (',
'                            SELECT SFI.STUDENT_ID, SFI.SITE_ID, SFI.FEE_MONTH, MIN(SFI.FEE_COLLECTION_ID)',
'                            FROM STUDENT_FEE_COLLECTION SFI',
'                            GROUP BY SFI.STUDENT_ID, SFI.SITE_ID, SFI.FEE_MONTH',
'                        )',
'                    ) ob',
'                        ON ob.STUDENT_ID = st.STUDENT_ID ',
'                       AND ob.SITE_ID = st.SITE_ID ',
'                       AND ob.FEE_MONTH = lf.MAX_FEE_MONTH',
'',
'                    WHERE st.STUDENT_ID = S.STUDENT_ID',
'                      AND st.SITE_ID =  S.SITE_ID',
'',
'',
'             )PRV_MONTHLY_FEE  -- GET PRV ALL MONTH FEE HOSE NOT PAID IF PAID THEN GET OP BALANCE--',
'',
'            FROM STUDENTS S',
'            JOIN CLASSES C ON S.CLASS_ID = C.CLASS_ID',
'            LEFT JOIN STUDENT_FEE_COLLECTION SFC',
'              ON S.STUDENT_ID = SFC.STUDENT_ID',
'              AND S.SITE_ID = SFC.SITE_ID',
'              AND TO_CHAR(TO_DATE(SFC.FEE_MONTH, ''MM-YYYY''), ''MM-YYYY'') = TO_CHAR(SYSDATE, ''MM-YYYY'')',
'            WHERE S.SITE_ID = :APP_SITE_ID',
'              --AND S.STATUS=''A''',
'            GROUP BY S.STAGE,S.ADMISSION_DATE,SFC.FEE_MONTH,S.STUDENT_ID,S.STUDENT_NAME,S.LAST_NAME,S.STUDENT_TYPE,S.STATUS,S.SITE_ID,C.CLASS_NAME,SFC.MONTHLY_FEE',
'          ) A',
'        ) B,STUDENT_FEES F   ',
'        WHERE B.STUDENT_ID=F.STUDENT_ID(+)  ',
'          AND B.SITE_ID   =F.SITE_ID(+)',
'          AND F.STATUS = ''A''',
'          AND F.FEE_START_DATE <= TRUNC(SYSDATE)',
'          )',
'  )  ',
' WHERE STUDENT_ID=NVL(:P88_STUDENT_ID,STUDENT_ID)',
'   AND (STATUS = ''Active'' OR CLOSING_BALANCE <> 0 AND FEE_MONTH IS NOT NULL)',
'   AND ((:P88_FEE_STATUS=''P'' AND (CLOSING_BALANCE > 0)) OR (:P88_FEE_STATUS=''A'' AND (CLOSING_BALANCE < 0)) OR :P88_FEE_STATUS IS NULL)      ',
'ORDER BY CASE',
'            WHEN STUDENT_ID LIKE ''K%'' THEN 1',
'            WHEN STUDENT_ID LIKE ''G%'' THEN 2',
'            WHEN STUDENT_ID LIKE ''A%'' THEN 3',
'          END,LENGTH(STUDENT_ID),STUDENT_ID',
'',
' ',
'',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P88_STUDENT_ID,P88_FEE_STATUS'
