prompt --application/pages/page_00089
begin
wwv_flow_imp_page.create_page(
 p_id=>89
,p_name=>'Weekly Progress Report'
,p_alias=>'WEEKLY-PROGRESS-REPORT'
,p_step_title=>'Weekly Progress Report'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function printdiv(printpage)',
'',
'{',
'',
'var headstr = "<html><head><title></title></head><body>";',
'',
'var footstr = "</body>";',
'',
'var newstr = document.all.item(printpage).innerHTML;',
'',
'var oldstr = document.body.innerHTML;',
'',
'document.body.innerHTML = headstr+newstr+footstr;',
'',
'window.print();',
'',
'document.body.innerHTML = oldstr;',
'',
'return false;',
'',
'}'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#weekly_report_region{',
'    border: none !important;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(45517020571344944112)
,p_plug_name=>'Weekly Report Region'
,p_region_name=>'weekly_report_region'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html   CLOB := '''';',
'    v_title  VARCHAR2(100);',
'BEGIN',
'    FOR r IN (',
'        SELECT ',
'            p.*, ',
'            s.STUDENT_NAME, ',
'            sb.SUBJECT_NAME, ',
'            b.BOOK_NAME, ',
'            e.EMP_NAME',
'        FROM STUDENT_PROGRESS p',
'        LEFT JOIN STUDENTS s ON s.STUDENT_ID = p.STUDENT_ID AND s.SITE_ID = p.SITE_ID',
'        LEFT JOIN SUBJECTS sb ON sb.SUBJECT_ID = p.SUBJECT_ID',
'        LEFT JOIN BOOKS b ON b.BOOK_ID = p.BOOK_ID',
'        LEFT JOIN EMPLOYEES e ON e.EMP_ID = p.EMP_ID',
'        WHERE p.STUDENT_ID = :P89_STUDENT_ID',
'          AND p.SITE_ID = :APP_SITE_ID ',
'          AND P.SP_ID   = :P89_SP_ID',
'          AND p.PROGRESS_TYPE = ''W''',
'        ORDER BY p.SP_DATE DESC',
'    ) LOOP',
'        v_title := CASE r.PROGRESS_TYPE',
unistr('                       WHEN ''W'' THEN ''\D83D\DCD8 Weekly Progress Report'''),
'                   END;',
'',
'        v_html := v_html || ',
'        ''<div id="weekly_progress" style="max-width:600px; margin:auto; padding:20px; font-family:sans-serif; background:#ffffff; border-radius:10px; box-shadow:0 0 10px rgba(0,0,0,0.1); line-height:1.6;">'' ||',
'',
'        ''<h2 style="text-align:center; color:#2c3e50;">Fine Tutors</h2>'' ||',
'        ''<h3 style="text-align:center; color:#2980b9; margin-bottom:30px;">'' || v_title || ''</h3>'' ||',
'',
'        -- Student Info',
'        ''<div style="margin-bottom:20px;">'' ||',
unistr('        ''  <p><strong>\D83C\DF93 Admission No:</strong> '' || r.STUDENT_ID || ''</p>'' ||'),
unistr('        ''  <p><strong>\D83D\DC64 Student:</strong> '' || NVL(r.STUDENT_NAME, ''-'') || ''</p>'' ||'),
unistr('        ''  <p><strong>\D83D\DCD6 Subject:</strong> '' || NVL(r.SUBJECT_NAME, ''-'') || ''</p>'' ||'),
'        ''</div>'' ||',
'',
'        -- Feedback',
'        ''<div style="background:#f9f9f9; padding:15px; border-radius:8px; margin-bottom:20px;">'' ||',
unistr('        ''  <h4 style="color:#27ae60;">\2705 What Went Well (WWW)</h4>'' ||'),
'        ''  <p>'' || NVL(r.WHAT_WANT_WELL, ''-'') || ''</p>'' ||',
