,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Sibling Fee Plan - Save Interactive Grid Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
' BEGIN',
'',
'    CASE :apex$row_status',
'      WHEN ''C'' THEN',
'          INSERT INTO SIBLING_FEE_PLAN(STUDENT_ID,STUDENT_TYPE,CLASS_ID,ADMISSION_FEE,REG_FEE_DISC,BOOKS_FEE,EXAMS_FEE,PAST_PAPERS_FEE,PAST_PAPER_DISC,',
'                                       TUITION_FEE_TYPE,TUTION_TIME,TUITION_FEE,HOURLY_FEE_DISC,MONTHLY_FEE,SIBLING_DISCOUNT,TOTAL_SIBLINGS_MONTHLY_FEE,',
'                                       SITE_ID,SUBJECT_ID,FEED_BY,FEED_DATE)',
'            VALUES(:STUDENT_ID,:STUDENT_TYPE,:CLASS_ID,:ADMISSION_FEE,:REG_FEE_DISC,:BOOKS_FEE,:EXAMS_FEE,:PAST_PAPERS_FEE,:PAST_PAPER_DISC,',
'                   :TUITION_FEE_TYPE,:TUTION_TIME,:TUITION_FEE,:HOURLY_FEE_DISC,:MONTHLY_FEE,:SIBLING_DISCOUNT,:TOTAL_SIBLINGS_MONTHLY_FEE,',
'                   :APP_SITE_ID,:SUBJECT_ID,:APP_USER,TRUNC(SYSDATE))',
'            ;',
'        WHEN ''U'' THEN',
'            UPDATE SIBLING_FEE_PLAN',
'            SET STUDENT_ID=:STUDENT_ID,STUDENT_TYPE=:STUDENT_TYPE,CLASS_ID=:CLASS_ID,ADMISSION_FEE=:ADMISSION_FEE,REG_FEE_DISC=:REG_FEE_DISC,',
'                BOOKS_FEE=:BOOKS_FEE,EXAMS_FEE=:EXAMS_FEE,PAST_PAPERS_FEE=:PAST_PAPERS_FEE,PAST_PAPER_DISC=:PAST_PAPER_DISC,TUITION_FEE_TYPE=:TUITION_FEE_TYPE,',
'                TUTION_TIME=:TUTION_TIME,TUITION_FEE=:TUITION_FEE,HOURLY_FEE_DISC=:HOURLY_FEE_DISC,MONTHLY_FEE=:MONTHLY_FEE,',
'                SIBLING_DISCOUNT=:SIBLING_DISCOUNT,TOTAL_SIBLINGS_MONTHLY_FEE=:TOTAL_SIBLINGS_MONTHLY_FEE,SUBJECT_ID=:SUBJECT_ID,                                      ',
'                FEED_BY      =:APP_USER,',
'                FEED_DATE    =TRUNC(SYSDATE)',
'            WHERE SIBLING_FEE_PLAN_ID = :SIBLING_FEE_PLAN_ID    ',
'            ;',
'        WHEN ''D'' THEN',
'            DELETE FROM SIBLING_FEE_PLAN',
'            WHERE SIBLING_FEE_PLAN_ID = :SIBLING_FEE_PLAN_ID   ',
'            ;    ',
'    END CASE;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(89541351041999549201)
,p_internal_uid=>89332702914699115605
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(89472074509305971114)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(88538945287669487809)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Sibling Fee Plan saveinto student fees'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'V_STUDENT_CNT NUMBER;',
' BEGIN',
'     SELECT COUNT(*) INTO V_STUDENT_CNT',
'            FROM STUDENT_FEES S',
'           WHERE S.STUDENT_ID = :STUDENT_ID',
'             AND S.SITE_ID    = :APP_SITE_ID',
'     ; ',
'        IF V_STUDENT_CNT = 0 THEN',
'          INSERT INTO STUDENT_FEES(STUDENT_ID,REGISTRATION_FEE,BOOK_FEE,EXAM_FEE,HOURLY_FEE,PAST_PAPER_FEE,SIBLING_DISC_PER,TOTAL_FEE,REG_FEE_DISC,PAST_PAPER_DISC,',
'                                   HOURLY_FEE_DISC,TUITION_FEE_TYPE,TUTION_TIME,DUE_DATE,FEE_START_DATE,SITE_ID,FEED_BY,FEED_DATE)',
'            VALUES(:STUDENT_ID,:ADMISSION_FEE,:BOOKS_FEE,:EXAMS_FEE,:TUITION_FEE,:PAST_PAPERS_FEE,:SIBLING_DISCOUNT,:TOTAL_SIBLINGS_MONTHLY_FEE,:REG_FEE_DISC,:PAST_PAPER_DISC,',
'                   :HOURLY_FEE_DISC,:TUITION_FEE_TYPE,:TUTION_TIME,1,TRUNC(SYSDATE),:APP_SITE_ID,:APP_USER,TRUNC(SYSDATE))',
'            ;     ',
'        END IF;    ',
'      DELETE FROM SIBLING_FEE_PLAN',
'        WHERE SIBLING_FEE_PLAN_ID = :SIBLING_FEE_PLAN_ID',
'          AND STUDENT_ID IS NOT NULL',
'          ;   ',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(89472074785253971116)
,p_internal_uid=>89472074509305971114
);
end;
