wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(90348517075434361207)
,p_name=>'Get OPN Balanace'
,p_event_sequence=>10
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P99_PARENT_NAME'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
